/* Evolvlings: English text for the era 4 path conversations (parallel to events-era4.js). */
window.EVEVENTS_EN = window.EVEVENTS_EN || {};
(function (E) {
  const add = (zone, evs) => { E[zone] = Object.assign(E[zone] || {}, evs); };

  /* ==================== Delivery 1: root metal, the strike, the stone hands and the Bell ==================== */

  add("crater", {
    "e4-fogarin": { who: { fogarin: "Fogarín, Master of the Guild" }, nodes: {
      a: { say: ["At the bottom of the Crater, where a stone slope used to be, there is now a wide pit with iron stairs. Down below, something red glows and never goes out. Up top, a very old man in the Master's apron waits for you beside an enormous mould.",
                 "Caretaker. Come, come. Look at this. It's the Bell's mould. When we cast it, the Root will sleep without anyone singing to it. Not you, not the Houses, not anyone who charges for the lullaby.",
                 "All my life I saw Fire bought. By the Houses, by water, by whoever had more. With this, Fire gives the Glade something nobody can buy. A bronze sleep for the Root."],
           opts: ["“Where does the metal come from?”", "“Who's going to ring the Bell?”", "“I've seen your workers' hands.”", "“The Houses sold their forges over the Tides' version.”", "“Help me understand how it works.”"] },
      metal: { say: ["From below. From very far below. It's hot and never cools, even if you put it in snow. The old folk said it was the Root's blood. The old folk said many things.",
                     "I say it's metal. And that with it you make things that couldn't be made before."] },
      quien: { say: ["That's the question. The Houses are already buying turns. As if the Bell were a furnace you could rent.",
                     "I want nobody who pays to ring it. But then I don't know who. That's why I'm asking you too."] },
      manos: { say: ["Yes. I've seen them.",
                     "He looks at his own hands. His nails have a grey line along the edge, fine, as if painted with ash.",
                     "The deep furnaces are tiring. Hands get hard with work. It was always like that in the Guild.",
                     "He doesn't look at you as he says it."] },
      mareas: { say: ["I bought them. Cheap. Ola told me not to. I did it anyway: if the Guild didn't buy them, someone else would.",
                      "Now I have more furnaces than anyone in the history of the Glade. And every day someone reminds me they were someone else's."] },
      ayudar: { say: ["Fogarín shows you the plans, the furnaces, the channel the metal will run along. He talks fast, with his hands, like the apprentice he was sixty years ago.",
                      "The bell rings once, and the note goes down to the bottom, to the Root. No eight verses to sing. No nine peoples to bring together. One note and that's it.",
                      "He says it as if that were the good part. You realise that, for him, it is."] },
    } },

    "e4-huelga": { who: { escoria: "Escoria, worker", cobre: "Cobre, of the Houses" }, nodes: {
      a: { say: ["At the entrance to the deep furnaces, a hundred workers sit on the ground with their arms crossed. In front of them, a woman with a soot-covered face shouts louder than everyone.",
                 "Not one more shovel! Not one more ingot! Let them go down to the deep furnaces, and see how long before they can't close their fist.",
                 "Behind you, a well-dressed young man takes you by the elbow. He wears a House crest on his chest, worn.",
                 "Caretaker. My name is Cobre. My House paid the Guild for the Bell, in advance. If the strike goes on, there's no Bell, and my House goes under. Take this to the worker: a purse for everyone who goes back to work."],
           opts: ["“Escoria, what exactly are you asking for?”", "Back the strike and sit with the workers", "Carry Cobre's message", "Mediate between the workers and the Guild"] },
      piden: { say: ["That the deep furnaces close. That root metal be dug only in short shifts. And that the Guild say out loud what's happening to our hands.",
                     "We're not asking for money. We've been given money. Money doesn't open fingers."] },
      apoyar: { say: ["You sit on the ground among the workers. After a while, your creature lies down beside you. The workers look at it, and one scratches its head with a hard, grey hand.",
                      "The Caretaker is with us. The Caretaker is with us!",
                      "Word spreads. That night the deep furnaces close. Fogarín doesn't come down to talk. Cobre leaves without saying goodbye.",
                      "The Guild won't forget this. Nor will the Houses. But the fingers that don't turn to stone this week are ours."] },
      recado: { say: ["You take the purse to Escoria. She opens it, looks inside and throws it at her feet.",
                      "A purse. For my hands.",
                      "But behind her, a young worker bends down and picks it up. Then another. The next day, half go back to the deep furnaces. Escoria stays alone at the entrance, shouting, louder than ever.",
                      "Thank you. My House doesn't forget those who help it. Nor those who don't."] },
      mediar: { say: ["You go up to talk to Fogarín. You go down to talk to Escoria. You go up again. It takes three days.",
                      "In the end there's a deal: one-hour shifts in the deep furnaces, and a worker who checks everyone's hands on the way out. Nobody's happy. Everybody signs.",
                      "This is little. But I signed it. If tomorrow I see one more hand of stone, I tear up the paper.",
                      "The Bell will be a year late. My House doesn't have a year. But fine. Thank you for not choosing."] },
    } },

    "e4-manos": { who: { yunque: "Yunque, smith" }, nodes: {
      a: { say: ["At the last furnace, the deepest, a smith as broad as a door hammers a red ingot. He wears an amulet with the face of a nameless statue. He strikes with one hand. The other rests on the anvil, still.",
                 "I can't move it. For a moon now. It doesn't hurt. It just weighs.",
                 "It's the Nameless Smith, the one of the third statue. He forged the Glade's first tools. If the same happens to me as to him, it's because I'm doing what he did. It's an honour."],
           opts: ["“Do you know how the Smith ended?”", "Tell all the workers about the statue", "Say nothing", "Tell only Yunque"] },
      termino: { say: ["He stayed in the Heart. Forever. As a statue. That's what the rites say.",
                       "They don't say why. I think because he'd finished his work. I want to finish mine too."] },
      contar: { say: ["You gather the shift's workers at the furnace mouth. You tell them about the third statue: the slag stuck to its base, just like on their hands. The smith who drew metal from below and ended up as stone.",
                      "Silence. Then a murmur. One worker looks at his nails. Another puts his shovel down and doesn't pick it up again.",
                      "You took away the honour. Now it's only fear.",
                      "The next day, half the workers don't go down. The deep furnaces run at half. Yunque goes down anyway, with his still hand."] },
      callar: { say: ["You say nothing. Yunque keeps hammering. The ingot goes black, then red again, as if it were breathing.",
                      "You know something. It shows. Well. Everyone carries their own.",
                      "The deep furnaces keep working at full fire. That night, in the Heart, someone leaves a candle at the foot of the third statue."] },
      yunque: { say: ["You wait for the others to leave. You tell Yunque, only him, about the statue and the slag.",
                      "Then it wasn't an honour. It was a price.",
                      "He stays a long while looking at his grey hand on the anvil.",
                      "I'll finish the Bell anyway. But I'll be the last to go down that deep. I'll send the others up. And I won't tell them why. If I tell them, they'll leave. And if they leave, the Bell doesn't get finished."] },
    } },

    "e4-ascuas": { who: { tizon: "Master Tizón" }, nodes: {
      a: { say: ["In an old house at the edge of the Crater, an old man counts coins on the table, each pile twice. He is over a hundred. His eyes are two tiny embers.",
                 "You. I remember you. From before everything. When the Night of Embers was a feast, and the furnaces went out one night a year so Fire would remember it also knows how not to burn.",
                 "It hasn't been held for forty years. The Guild says it's a lost night of work. I say it's the only night Fire doesn't drink. Nobody remembers what it was like any more."],
           opts: ["“What was the Night of Embers like?”", "Bring back the Night of Embers this year", "“Leave it forgotten. It doesn't belong to these times.”"] },
      como: { say: ["Every furnace went out at sunset. Every one. The song of Fire was sung with cold hands. And in the morning only one was lit, with an old ember, and from that one the others were lit.",
                    "It was to remember that Fire begins in a single ember. That it belongs to nobody. I've forgotten the song's words. I remember the tune."] },
      revivir: { say: ["You go from furnace to furnace with Tizón, who walks with two canes. He talks to the masters. You talk to the workers. Some laugh. Many don't.",
                       "At sunset on the shortest day, the furnaces go out. Not all: the deep ones keep burning, because root metal won't let itself be put out. But the others do. The Crater goes dark for the first time in forty years.",
                       "Someone hums the tune. Others join in. Nobody knows the words. Escoria, in the dark, makes some up.",
                       "It wasn't like that. But it's close. In the morning I'll light the first one. With an old ember. I've kept one for forty years."] },
      olvidar: { say: ["Forgotten. Yes. Like me.",
                       "He goes back to counting the coins. He loses count. He starts again.",
                       "When I die, there'll be nobody left who remembers the tune. Well. Maybe Fire doesn't need to remember anything. Maybe that's why it drinks so much."] },
    } },
  });

  add("aurora", {
    "e4-cobre": { who: { cobre: "Cobre, of the Houses" }, nodes: {
      a: { say: ["In the Meadow square there's an enormous board with squares. Each square is a night of the year. Half already have a House crest painted on. A young man, in a good coat with worn cuffs, paints another.",
                 "Bell turns. Whoever holds the night decides whether the Root sleeps that night or not. If it sleeps, nothing moves under the Meadow. If not, you can dig.",
                 "My House bought eight nights with the last of what it had. If the Bell isn't finished, my House is finished. So, you see, Caretaker: I'm for the Bell."],
           opts: ["“And why would they want the Root not to sleep?”", "“The Court didn't forget the Chronicle, did it?”", "“Let your House buy a night for the Quarter.”", "“Selling nights of sleep is selling the Root.”"] },
      para: { say: ["To dig, of course. When the Root sleeps, you can't draw metal from below: the ground closes. When it's awake, it opens. That's how it is.",
                    "Don't look at me like that. My great-grandmother sold light. My grandmother, candles. My mother, nothing. I sell nights. It's what there is."] },
      corte: { say: ["No. They buy nights too, under another name. On the nights they hold, the Root doesn't sleep, and the ground opens beneath the Meadow.",
                     "Fifty years of the Official Chronicle and the Court collects on it one night at a time."] },
      barrio: { say: ["A night for the Quarter? For free?",
                      "He looks at the board. At the brush. He paints a square, the longest night of the year, with a crooked drawing of a door with no lantern.",
                      "Let them decide it. One night. My mother would die all over again if she saw it. But the Houses can't go to the Heart asking without having given anything."] },
      vender: { say: ["Everything gets sold, Caretaker. Water got sold. Light got sold. If I don't sell it, someone else will, and someone else keeps the House.",
                      "He finishes painting the crest. His hand shakes a little."] },
    } },

    "e4-chispa": { who: { chispa: "Chispa", tizon: "Master Tizón" }, nodes: {
      a: { say: ["On the road from the Meadow to the Crater, a skinny girl from the south slope crouches beside an ingot fallen from a cart. She touches it with a fingertip. Pulls back. Touches it again.",
                 "It doesn't burn that much. It burns nice. Like when you sit really close to the fire in winter.",
                 "My name's Chispa. I want to learn to forge. They won't let me into the Guild because I'm from the south slope and I don't have a furnace surname. But I know my hands are good for it."],
           opts: ["“Look at your finger.”", "Take her to Master Tizón", "Give her a hammer and tell her to forge with common iron", "“Don't touch that. Go home.”"] },
      dedo: { say: ["Chispa looks at her fingertip. There's a little grey spot, the size of a lentil, where she touched the ingot.",
                    "It'll go away. It comes off with water. Right?",
                    "She rubs it on her dress. It doesn't come off."] },
      tizon: { say: ["Tizón looks at her from his chair. He makes her clench a fist, open her hand, hold an empty pair of tongs.",
                     "She has forge hands. A pity she was born in these times. I'll teach her to forge cold. River iron. No metal from below.",
                     "Cold? That's for little kids.",
                     "That's for people who want to have hands when they're old. Learn that first. The other thing, anyone can learn."] },
      martillo: { say: ["You give her a small hammer from your belt. Chispa holds it with both hands, like a treasure.",
                        "Common iron. Fine. I'll still make something with this. Something nobody's made.",
                        "She runs off towards the slope. From the fallen ingot on the road rises a thin smoke that smells of scorched earth."] },
      casa: { say: ["You too. Everyone tells me that.",
                    "She leaves. But first, when she thinks you're not looking, she touches the ingot again with her fingertip."] },
    } },
  });

  add("forest", {
    "e4-tala": { who: { hacha: "Hacha, woodcutter" }, nodes: {
      a: { say: ["In the Deep Wood there's a sound that was never heard before: axes, many of them, all day long. Where a three-hundred-year-old oak stood there's a stump as wide as a table, dripping resin as if it were weeping.",
                 "The Guild pays three times what the Council pays for looking after the trees. The deep furnaces need wood to heat the cold metal before mixing it with the root metal.",
                 "My grandmother looked after these trees. I cut them down. My daughter will eat this winter. You do the sums."],
           opts: ["“What does the Council say?”", "“For every tree you cut, plant three.”", "Hide their axes for a night", "Help her carry the wood"] },
      concejo: { say: ["The Council says no. The Council has said no to everything for a hundred years. While they say no, the Guild pays.",
                       "If the Council paid as much for caring as the Guild pays for cutting, there'd be no axes in the Wood. But the Council has no furnaces. It has moss."] },
      plantar: { say: ["Three? And who pays for the saplings?",
                       "She thinks it over with her axe on her shoulder. Then she whistles loudly. The other woodcutters stop cutting.",
                       "Three for every one. We'll pay for it, out of our wages. And we'll bill the Guild for it later, in the Heart, when it's time to talk about who pays for what. Let the Council see the Wood also knows how to care without saying no."] },
      esconder: { say: ["At night you hide the axes in a hollow under the roots of an old tree. In the morning, the woodcutters search the whole clearing for them.",
                        "Hacha finds them at noon. She looks at you from a distance. She says nothing. That afternoon they cut twice as much, to make up for the lost day."] },
      cargar: { say: ["You carry wood with her to the cart. It's heavy, damp, and smells of resin. By the end of the day your arms are covered in scratches.",
                      "Thank you. Nobody from outside helps us. They look at us as if we were the Guild. We're not the Guild. We're the ones the Guild uses."] },
    } },

    "e4-resina": { who: { hacha: "Hacha, woodcutter", escoria: "Escoria, worker", fogarin: "Fogarín, Master of the Guild" }, nodes: {
      a: { say: ["In the clearing of stumps, Escoria sits with her hands sunk to the wrists in a bucket of warm resin. Her eyes are closed. Hacha watches her with her arms crossed.",
                 "It softens. The resin of old trees softens the hands. It doesn't cure them, but it softens them. I can close my fist again.",
                 "Only the old trees' resin. The three-hundred-year-old ones. For one bucket you have to cut one down. And there are four hundred workers with grey hands in the Crater."],
           opts: ["“How many old trees are left?”", "“Cut as many as it takes. Hands first.”", "“Not one more. Find another way.”", "“One bucket per furnace, and the Guild pays.”"] },
      cuantos: { say: ["Two hundred, maybe. There used to be thousands. The furnaces of before took them, and the ones before those.",
                       "Two hundred trees. Four hundred hands. I'm not going to choose which is worth more. That's what the people in charge are for."] },
      cortar: { say: ["That week twenty old trees come down. The resin goes in buckets to the Crater. The workers put their hands in and pull them out soft, pink, and some of them cry.",
                      "Twenty. In a week. My grandmother spent her whole life watching one grow.",
                      "Thank you. I don't care about the Wood. I care about these fingers. But thank you."] },
      ninguno: { say: ["Another way? Which? Tell me and I'll use it.",
                       "You have no answer. Escoria takes her hands out of the bucket. They stiffen again as you watch.",
                       "It's not fair on her. But it's not fair on the trees either. Sometimes nothing's fair, and you have to choose anyway."] },
      gremio: { say: ["You take the proposal to the Guild. Fogarín signs it that same afternoon, without haggling: one bucket of resin per furnace, per moon, paid by the Guild, and three saplings for every tree.",
                      "I'm not doing it to be good. I'm doing it because if the workers can't close their fists, there's no Bell.",
                      "I don't care why. He signed it. That stays."] },
    } },
  });

  add("hollow", {
    "e4-hulla": { who: { hulla: "Hulla, Court charcoal burner" }, nodes: {
      a: { say: ["Behind the Hollow, in a smaller hollow, there are mountains of charcoal as black as holes. A woman in a grey veil, her hands stained, covers them with tarpaulins so they can't be seen from above.",
                 "Shadow charcoal. The wood here, burned slowly underground, makes a charcoal that burns without smoke. The Guild uses it for the deep furnaces, where smoke has nowhere to go.",
                 "We sell it by the back door. If the Houses knew the Court was heating the Bell, they'd stop buying turns. And the Court needs the coins."],
           opts: ["“Why hide it?”", "“Sell it in broad daylight, under the Court's name.”", "“Let the Quarter have charcoal this winter.”", "Tell Cobre"] },
      esconder: { say: ["Because the Court has always done things behind people's backs. It's what it knows how to do. It did it with the sap, with the wells, with the visions.",
                        "And because if it's known, they'll blame us again. For the Bell, for the hands, for whatever happens next. They blamed us once already for a night that belonged to everyone."] },
      luz: { say: ["Under the Court's name? Let everyone see we're part of this?",
                   "She looks at the tarpaulins. At the charcoal. She takes off her veil and folds it.",
                   "All right. If they're going to blame us, let it be for something we really did, and in plain sight. Let it be seen too that the Bell has something of ours. When the Heart calls, the Court will be there."] },
      barrio: { say: ["Hulla sends three carts to the Quarter that same night, with no note, no veil, no crest.",
                      "For the wells. For the Night of Lanterns. For whatever it was. It's not forgiveness. It's charcoal."] },
      cobre: { say: ["Cobre finds out that same afternoon. The next day, the Houses hand back twelve Bell turns. They demand the Guild stop buying charcoal from the Court.",
                     "I knew it would happen. It always does. The Court keeps the charcoal and loses the coins. And the Guild buys the charcoal anyway, cheaper, at another back door."] },
    } },

    "e4-ebano": { who: { ebano: "Ébano, Court archivist", yunque: "Yunque, smith" }, nodes: {
      a: { say: ["In the Court archive, a young archivist with a new veil and clean hands unrolls a parchment so old it crumbles at the edges.",
                 "This was in the oldest box. It's a list of the Glade's first forges. And at the end, crossed out in ink from another age, a name: that of the smith who drew the first metal from below.",
                 "The Nameless Smith had a name. Someone erased it. And the seal that crossed it out belongs to the Ember Guild."],
           opts: ["“Why would the Guild have erased it?”", "“Take it to Yunque. He prays to that man.”", "“Show it in the Heart, to everyone.”", "“Keep it. This isn't the moment.”"] },
      porque: { say: ["I suppose because a smith with a name is a man who died of his work. A smith without a name is a saint.",
                      "Saints get prayed to. The dead of work get paid. The Guild preferred to pray."] },
      yunque: { say: ["You take the parchment to the Crater. Yunque holds it with his good hand. The other hangs, grey, at his side.",
                      "He reads the name under his breath. He doesn't repeat it. He folds it and keeps it in the amulet, behind the nameless face.",
                      "Now I know who I'm praying to. Not a saint. A worker nobody looked after. I'll finish the Bell for him. And afterwards I'll say his name out loud."] },
      corazon: { say: ["Ébano takes the parchment to the Heart and nails it to the base of the third statue, over the slag.",
                       "Guild folk tear it down that same night. The next day there are four copies nailed up. Someone at Court spent the night copying.",
                       "The Court knows how to hide things. This time it knew how to show them. It's the first time I've felt proud of the veil."] },
      guardar: { say: ["You're right. If it comes out now, the Guild will say the Court made up the paper to stop the Bell.",
                       "He rolls it up carefully and puts it in a new box, under lock and key.",
                       "Some day someone will need that name. I hope it isn't too late."] },
    } },
  });

  add("lake", {
    "e4-hierve": { who: { salitre: "Salitre, fisher", fogarin: "Fogarín, Master of the Guild" }, nodes: {
      a: { say: ["On the south shore of the Mirror Lake steam rises from the water as from a pot. White fish float, cooked. A Tides woman gathers them with a net, looking disgusted.",
                 "There are furnaces underneath. The Guild's deep furnaces, dug under the Crater until they got here. The water boils where they are.",
                 "My grandmother sold water. My mother looked after it. I gather cooked fish nobody wants to buy because it smells of metal. The Tides always pay for what others do down below."],
           opts: ["“Does the Guild know this is happening?”", "“Let the Guild pay the Tides for every furnace under the lake.”", "Dive near the steam to see what's there", "Help her gather the fish for the Quarter"] },
      sabe: { say: ["It knows. We sent it a boat full of cooked fish. They sent us a bag of coins and a note: “Thank you for the fish.”",
                    "That's how they are. They pay you to keep quiet, and call it buying."] },
      pagar: { say: ["You go to the Crater with Salitre and a boatload of cooked fish. Fogarín looks at them, one by one, for a long time.",
                     "I grew up among the Tides. Ola taught me to swim. And now I'm boiling their lake.",
                     "He signs a paper: a coin per cooked fish, every week, for as long as there are furnaces underneath. It isn't much. It's something.",
                     "Nobody ever paid us for what they took. The Tides will go to the Heart with this paper. Let it be seen."] },
      bucear: { say: ["You wade into the warm water. The deeper you go, the hotter it gets. Below you see a red light, and walls of carved stone, old, very old.",
                      "You come up before it hurts. Your skin is red as a shrimp.",
                      "Did you see something? You look like you saw something."] },
      barrio: { say: ["You gather the fish in baskets and carry them to the Quarter. They smell of metal, but they're cooked and they're free.",
                      "They eat them anyway. Hunger has no sense of smell. That's what my grandmother used to say."] },
    } },

    "e4-forjahundida": { who: { salitre: "Salitre, fisher", yunque: "Yunque, smith" }, nodes: {
      a: { say: ["The water has dropped again where it boils, and on the south shore a stone structure nobody had seen shows through: an ancient furnace, round, its mouth facing the lake. Inside, still, a red ember.",
                 "It's a forge. Under the water. Older than anything the Guild has.",
                 "On the furnace stone there are handprints. Many, carved, as if someone had pressed their hands to the hot stone to leave the mark. The last prints are stone too: they're stuck to the wall, like grey gloves."],
           opts: ["Touch the stone handprints", "Tell the Guild", "Cover it with mud so the water covers it again", "Bring Yunque"] },
      tocar: { say: ["You touch one of the stone hands stuck to the wall. It's warm, like a real hand.",
                     "For an instant you feel a weight in your fingers, as if they'd gone to sleep. You pull your hand away. The weight goes slowly.",
                     "The colour's gone from your face. What did you feel?",
                     "You can't explain it. Something that stayed here working until it couldn't move any more."] },
      gremio: { say: ["Three Guild masters arrive with torches. They stare at the furnace open-mouthed. One takes out a notebook and starts measuring.",
                      "There. Now they'll want to use it. A forge that never went out. It'll look like a gift to them.",
                      "The next day there's a rope around the furnace and a sign with the Guild's crest."] },
      tapar: { say: ["You pile mud over the furnace mouth until the ember can't be seen. That night the water rises and covers everything again.",
                     "Let it stay down there. What was below, below. My grandmother said that about the lake. We never listened to her."] },
      yunque: { say: ["Yunque comes walking from the Crater, his grey hand hanging. He goes into the sunken furnace. He puts his good hand on one of the stone prints. It fits exactly.",
                      "He worked here. Here. Not in the Crater. The first one didn't forge in the mountain. He forged in the water, so the metal would cool.",
                      "And his hands went anyway. Water and all. So there's no way to work that metal without paying for it."] },
    } },
  });

  add("caves", {
    "e4-galena": { who: { galena: "Galena, miner" }, nodes: {
      a: { say: ["The new tunnels in the Caves aren't cold. You go down and the air gets warm, then hot. A Hondura miner, her helmet dented and her back soaked, pushes a wheelbarrow full of red stones.",
                 "Root metal. The Guild pays by the barrow. The Hondura has never earned so much. My grandfather knocked on walls for the dead. I knock on them for the Guild.",
                 "The trouble is, the deeper you go, the hotter. And sometimes the wall answers. You knock, and the wall knocks back. From the other side."],
           opts: ["“Who knocks from the other side?”", "“Let the Hondura stop digging the hot tunnels.”", "Help her push the wheelbarrow", "“Ask the Guild for more. You risk more than anyone.”"] },
      quien: { say: ["Nobody, say the foremen. It's the rock expanding with the heat.",
                     "My grandfather taught me to count knocks. These come two by two. Like the Hondura's when it's warning that someone was left below."] },
      parar: { say: ["Stop? With what it pays?",
                     "But she takes off her helmet. She wipes her hand across her face, black with dust.",
                     "My grandfather didn't dig for money. He dug so nobody would forget. I'll talk to the others. If the wall knocks two by two, someone is warning us. The Hondura will go to the Heart with that, not with wheelbarrows."] },
      empujar: { say: ["You push the wheelbarrow to the tunnel mouth. It weighs as if it were full of lead. When you reach the top your hands are hot, red.",
                       "Thanks. Now wash your hands well in cold water. Well. The ones who don't wash them, by next moon they don't close them the same."] },
      mas: { say: ["Galena goes to the Guild with other miners and asks for double. They give it without arguing.",
                   "Without arguing. That's what scares me. If they give you double without arguing, it's worth triple."] },
    } },

    "e4-veta": { who: { galena: "Galena, miner" }, nodes: {
      a: { say: ["In the deepest tunnel, Galena shows you a red vein running through the wall like a blood vessel. It glows. And it moves: very slowly, rising and falling, like a chest breathing.",
                 "It beats. Put your hand there. Don't touch the metal: put your hand near it.",
                 "You hold your hand a palm's width from the vein. You feel the heat. And a rhythm, slow, deep: one, pause, one, pause. Like the heart of something very large that sleeps."],
           opts: ["“It's the Root. This is part of the Root.”", "Draw a map of the vein", "Seal the tunnel", "Sing the lullaby to the vein"] },
      raiz: { say: ["The Root? We're taking pieces of the Root? To make a bell that puts it to sleep?",
                    "She stares at the full wheelbarrow.",
                    "It's like drawing someone's blood to make them a sleeping draught. And they fall asleep because you drew their blood."] },
      mapa: { say: ["You follow the vein with a lamp for hours. It runs down and to the north. Towards the Heart.",
                    "All the veins run the same way. If this is what I think, the Bell is being made from the very thing it's going to put to sleep."] },
      sellar: { say: ["You block the tunnel with stones and mortar. Galena knocks twice on the sealed wall, in farewell.",
                      "From the other side, far off, very slowly, two knocks answer.",
                      "There. Let nobody dig here. I'll write it in the Hondura's book. In big letters."] },
      nana: { say: ["You sing the lullaby softly, close to the vein. The rhythm slows. The glow dims, like an ember covering itself with ash.",
                    "It's falling asleep. With the lullaby it falls asleep on its own. It doesn't need a bell. It needs someone to sing to it.",
                    "When you stop singing, the glow comes back, slowly. But slower than before."] },
    } },
  });

  add("heights", {
    "e4-peaje": { who: { peaje: "Peaje, carter" }, nodes: {
      a: { say: ["Up the northern pass climbs a line of carts with ingots under tarpaulins. The wheels leave two smoking lines in the snow. A Heights carter, his face burned by cold and heat at once, guides the oxen.",
                 "Root metal for outside. Beyond the mountains they pay what nobody here would. They say they make swords from it that never chip.",
                 "The Heights always carried things from one side to the other. Messages, verses, water. Now we carry this. What weighs, pays."],
           opts: ["“Does the Guild know it's sold outside?”", "“Let the Heights not take the metal out of the Glade.”", "“Charge a toll, and let it go to the workers.”", "Help him over the pass"] },
      sabe: { say: ["The Guild sells it. We carry it. The Houses buy it here and resell it there. Everyone knows. Nobody says.",
                    "What leaves the Glade doesn't come back, the old folk say. But the coins come back. Those always do."] },
      quedar: { say: ["And what do the Heights live on? Wind?",
                      "He looks at the smoke lines in the snow. At the valley below, where the Crater's smoke can be seen.",
                      "All right. This trip is the last. Heights carts take no more metal from under the Glade. Let others take it, if they want, but not over our passes. That's what we'll say in the Heart."] },
      cobrar: { say: ["Peaje raises a barrier on the pass and charges a coin per ingot. He sends the coins in a bag, every moon, to the Crater, for the workers with grey hands.",
                      "It isn't much. But the metal that leaves pays something of what it costs to dig. Before, it paid nothing."] },
      cruzar: { say: ["You help push the carts up the steepest part. The snow melts under the wheels and the mud comes up to your ankles.",
                      "Thanks. On the other side nobody knows where the Ford is. But they'll use metal that passed through your hands."] },
    } },

    "e4-alud": { who: { peaje: "Peaje, carter" }, nodes: {
      a: { say: ["In the high-slope village, below the pass, people look at the mountain in fear. The hot carts melted the snow lower down. The snow above is left hanging, enormous, with nothing to hold it.",
                 "If it falls, it takes the village. Thirty houses. The old folk won't leave. They say the mountain hasn't fallen in a thousand years.",
                 "The mountain hasn't had hot carts going over it in a thousand years either, I tell them."],
           opts: ["Help get the people out of the village", "Bring the snow down early, carefully, with everyone far away", "“Let the carts stop until it snows again.”"] },
      sacar: { say: ["You spend the day carrying old folk, goats and boxes. By nightfall, the village is empty. Two old women refuse to leave. You leave them blankets and a candle.",
                     "The snow doesn't fall that night. Nor the next. On the third, it falls. The two old women got out at the last moment. Of the village, only the roofs are left.",
                     "Thirty houses. All for a metal going outside."] },
      caer: { say: ["With everyone far away, Peaje and the carters throw stones from one side until the snow breaks loose. It falls with a noise heard all the way to the Crater.",
                    "It takes half the village. The other half is left standing. Nobody dies.",
                    "Half. Well. The old folk will hate me all my life. But they'll be alive to hate me."] },
      parar: { say: ["Stop the carts? Until winter?",
                     "He talks to the other carters. They argue at the top of their voices. In the end, the line of carts waits in the valley, the ingots smoking under the tarpaulins.",
                     "Two weeks later it snows. The new snow holds up the old. The village is saved whole. The Guild gets its ingots fifteen days late, and Fogarín says nothing."] },
    } },
  });

  add("deep", {
    "e4-deshielo": { who: { tempano: "Témpano, ice keeper", fogarin: "Fogarín, Master of the Guild" }, nodes: {
      a: { say: ["In the White Deep, things drip. The ice roofs drip, the walls, the icicles over the doors. It's a sound nobody here had ever heard. An old keeper puts buckets under the leaks.",
                 "The ice is melting. For the first time. My grandmother said the Deep's ice was eternal. That the Root made it to keep something.",
                 "Now the heat comes from below. From the Guild's furnaces, dug under everything. The Deep never had to defend itself from fire. We don't know how."],
           opts: ["“What did the ice keep?”", "“Go to the Guild and demand they close the furnaces under the Deep.”", "Help her move people to the high caves", "Gather the meltwater and keep it"] },
      guardaba: { say: ["Nobody knows. The stories say the cold. That the Root kept all the Glade's cold here for when it was needed.",
                        "If it melts, where does the cold go? Is it lost? Or does it all come back at once, some day?"] },
      exigir: { say: ["Témpano goes down to the Crater with four Deep keepers, wrapped in furs, in the full heat. Fogarín receives them sweating.",
                      "Closing the furnaces under the Deep means delaying the Bell a year.",
                      "Not closing them means the Deep stops existing. Choose which year you'd rather lose.",
                      "Fogarín closes two of the five furnaces. Témpano goes back without a word of thanks. The White Deep will go to the Heart, she says, to tell what happens when fire doesn't ask."] },
      mudar: { say: ["You help take the old and the children to the high caves, where the ice doesn't drip yet. It takes a week.",
                     "We're moving upwards. As if we were fleeing the ground. The White Deep climbing. My grandmother would die of shame."] },
      guardar: { say: ["You gather the water from the leaks in wooden barrels. It's clear water, very cold, that doesn't warm even if you leave it in the sun.",
                       "Kept cold. If the ice goes, at least let this remain. Some day someone will need it."] },
    } },

    "e4-aguanegra": { who: { tempano: "Témpano, ice keeper" }, nodes: {
      a: { say: ["Where the Deep's oldest ice melted, the ice under the hall of the Watch, black water appears. It isn't water: it's thick, it glistens, and it smells of something you've known for a long time.",
                 "Sap. Black sap, the old kind. It was frozen down here, for I don't know how many eras. The ice held it still.",
                 "Now it's moving. Slowly. South, towards the Heart. As if something were calling it."],
           opts: ["Gather it in barrels before it gets far", "Freeze it again with the kept cold water", "Follow it to see where it goes", "“Warn every people.”"] },
      juntar: { say: ["You spend two days filling barrels with wooden shovels. The sap sticks to everything. Your arms are black to the elbows.",
                      "On the third day, Cobre turns up with two carts and a purse. He wants to buy the barrels. He says the Houses remember what sap was worth.",
                      "I won't sell it to him. But now he knows it exists. And if he knows, everyone knows."] },
      congelar: { say: ["You pour over the sap the cold water you kept from the thaw. Where it falls, the sap goes hard, dull, still.",
                        "It works. Old cold serves for old things. But there's no cold water left. If it melts again, there's nothing to do it with."] },
      seguir: { say: ["You follow the black thread under the ice for hours. It runs down through cracks, under a river, into the rock. Always south.",
                      "At last it joins another thread, red, coming from the Crater. The two go into the earth together, towards the Heart.",
                      "The old sap and the new metal go to the same place. I don't know what it means. I don't like it."] },
      avisar: { say: ["You send warnings with everyone who passes. In a week, the news is in every people: there's black sap in the White Deep.",
                      "Some are afraid. Many remember the stories. A few start asking what it's worth.",
                      "Warning is right. But warnings are heard by those who shouldn't hear them too."] },
    } },
  });

  add("heart", {
    "e4-campana": { who: { fogarin: "Fogarín, Master of the Guild", retama: "Retama, keeper of the Stump" }, nodes: {
      a: { say: ["In the Heart, beside the third statue, a small bell hangs from a wooden scaffold, the size of a bucket, of a red that never goes out. It's the first test one. The big one is still being cast.",
                 "This one already works. We tried it last night. It rings, and for an hour, all over the Heart, the Root doesn't move. Not a tremor.",
                 "I'm Retama. I've kept the Stump since old Brezo died. And I'm telling you: that hour wasn't sleep. It was something else. The creatures didn't go near the Stump all night.",
                 "The Houses want to take it to the Meadow, for the turns. I don't know who to give it to. You decide. You're the one person nobody has ever bought anything from."],
           opts: ["“What did the Root feel when it rang?”", "Give it to the Houses", "Take it to the Ford", "“Let nobody have it. Let it stay here, unrung.”"] },
      sintio: { say: ["I don't know what the Root feels. Nobody does. But the Stump's roots went cold as stone. And the flowers around it closed at midnight, as if it were day.",
                      "Because it slept. That's what sleeping is.",
                      "That's going quiet. It's not the same."] },
      casas: { say: ["The small bell goes down to the Meadow in a House cart. Cobre receives it with shaking hands.",
                     "Well. That's it. They paid. Maybe that's fair.",
                     "Now the Root sleeps when a House pays. Let someone remember this day."] },
      vado: { say: ["You carry the small bell to the Ford, wrapped in a blanket. It weighs as if you were carrying a sleeping child.",
                    "You hang it at the entrance, away from the creatures. Nobody touches it. Your creature looks at it every morning from a distance, ears down.",
                    "At the Ford. Where nothing is sold. All right. Let whoever looks after things ring it, if it's ever needed."] },
      nadie: { say: ["Unrung? All that forging for nothing?",
                     "Retama ties the bell's tongue with a rag and a rope. The bell is left hanging from the scaffold, mute, beside the smith's statue.",
                     "Not for nothing. So it can be seen that it could be done, and that the choice was not to. That has to be forged too.",
                     "Fogarín leaves without saying goodbye. That night he's seen sitting at the foot of the third statue, his hand on the slag."] },
    } },

    "e4-final": { who: { fogarin: "Fogarín, Master of the Guild", escoria: "Escoria, worker", retama: "Retama, keeper of the Stump" }, nodes: {
      a: { say: ["The Hot Root falls, and the Heart's ground stays warm, like a kitchen floor. Above, on the scaffold, hangs the big Bell, finished. It's red and never goes out.",
                 "It's ready. One note and the Root sleeps forever. Nobody else has to go down to the deep furnaces, because no more metal is needed. Nobody else turns to stone.",
                 "And nobody sings to it any more. And nobody knows what happens to something that sleeps like that, with nobody singing to it, forever.",
                 "There's something else that can be done. Put out the furnaces. All of them. Not for one night: forever. Let Fire stop drinking altogether."],
           opts: ["“What happens if I ring the Bell?”", "“And if we put out every furnace?”", "“And if no one person decides?”", "Ring the Bell", "Put out every furnace in the Glade", "Share out the metal: one small forge per people, with all nine as witnesses"] },
      q1: { say: ["The Root sleeps. Deeply. No more tremors, no more sap, no more thirst. The deep furnaces close because they're no longer needed.",
                  "And the Root hears nothing any more. No lullabies, no footsteps, nothing. Something deaf asleep beneath everything. I don't know what that is, but it isn't peace."] },
      q2: { say: ["The stone hands end. The root metal ends. The Guild ends too. And us.",
                  "Fire doesn't know how to do anything but burn. With no furnaces, Fire goes down to the Ford to beg. All my life I saw Fire bought. Now I'd see it begging."] },
      q3: { say: ["The metal gets shared out. One small forge per people. No deep ones. Each people draws little, and pays little.",
                  "And the thirst gets shared. A little everywhere. The Root cools on every side at once. That only works if all nine say yes. If one's missing, that one builds its deep forge, and it all comes back."] },
      campana: { say: ["You climb the scaffold. Fogarín hands you the mallet. It weighs as if it were made of stone.",
                       "You strike. The note is so deep it can't be heard: it's felt in the bones, in the teeth, in the ground. It goes down to the bottom. Below, something enormous stops moving.",
                       "There. There. Nobody else.",
                       "Listen. You can't hear anything now. Not even the Heart's birds.",
                       "That night it starts to snow. It's early for snow. Nobody thinks much of it."] },
      ascuas: { say: ["You go down to the Crater with Escoria and Retama. Furnace by furnace, they go out. The workers help. Some cry. Some smash their shovels on the ground.",
                      "The deep furnaces don't go out with water. They're stopped with stones, with earth, with whatever there is. It takes a whole week.",
                      "There. Not one more hand of stone. And no work either. Tomorrow I'm going to the Ford to see if anyone needs firewood. Me, who had four hundred workers behind me.",
                      "The Bell stays hanging in the Heart. Cold. Mute. It's the greatest thing I made in my life, and it's a statue."] },
      forja: { say: ["The nine arrive. Each brings something: Escoria's strike, the Wood's resin, the Court's charcoal, the Tides' paper, the Hondura's book, the Heights' closed passes, the Deep's claim, the Night of Embers, the turn the Houses gave away.",
                     "Fogarín melts down the big Bell. The red metal is shared into nine ingots. Each people takes one for a small forge. No deep ones. No furnace going down further than an arm.",
                     "Little forge. Little metal. Few stone hands. Little of everything.",
                     "And little thirst. Everywhere. The Root neither sleeps nor wakes: it cools, slowly, on every side at once. I don't know if that's good. It belongs to everyone."] },
    } },
  });
  /* ==================== Delivery 2: the Day (Dawn Meadow, Warm Crater, Deep Forest) ==================== */

  /* ---------- Dawn Meadow: the board of nights, the ground that opens and the auction ---------- */
  add("aurora", {
    "e4-tablero": { who: { cerillo: "Cerillo" }, nodes: {
      a: { say: ["In front of the board of Bell turns, a barefoot boy from the Quarter counts the squares with his finger. His lips move. He gets it wrong and starts again.",
                 "Three hundred and sixty-five. And not one has a door without a lantern. Well, one does, but they painted it not long ago.",
                 "My grandmother says the Root used to sleep when someone sang to it. Now it sleeps when someone pays. How much is one night? So I know how much I have to save."],
           opts: ["“What do you want a night for?”", "Tell him the real price", "Teach him the lullaby, which costs nothing", "Draw a square with him, in chalk, without paying"] },
      para: { say: ["So the Root sleeps on my sister's birthday. That night the Quarter always shakes. The cups fall. She cries.",
                    "One still night. That's all. So nothing falls."] },
      precio: { say: ["You tell him what the House of Cobre paid for eight nights. Cerillo works it out in the dust with a stick.",
                      "Two hundred years of collecting tins. Fine. Now I know.",
                      "He rubs out the sum with his foot. He doesn't cry. He keeps looking at the board a while longer, the way you look at a shop window."] },
      nana: { say: ["You sit with him on the edge of the fountain and sing him the lullaby, slowly, twice. Cerillo repeats it, off-key.",
                    "And this makes it sleep? Without paying?",
                    "You tell him it used to. That you don't know if it's enough now. Cerillo shrugs.",
                    "I'll sing it that night anyway. If it doesn't work, at least my sister falls asleep."] },
      tiza: { say: ["You pick up a piece of chalk from the ground. On the edge of the board, outside the squares, Cerillo draws one more: a night that isn't in the year, with a cup standing in the middle.",
                    "The next day there are ten chalk squares. The day after, forty. The Houses send people to rub them out. They come back.",
                    "They don't do anything. I know. But now everyone sees nights are missing."] },
    } },

    "e4-badajo": { who: { badajo: "Badajo, bell-ringer of the Houses" }, nodes: {
      a: { say: ["In the courtyard of a House, a young man strikes a wooden bell with a leather-wrapped mallet. It makes no sound. He strikes again. He counts out loud.",
                 "They're teaching me to ring the Bell. The Houses want their own ringer for when they bring it. I practise on wood because the real one, the test one, deafens whoever rings it up close.",
                 "I can't hear well in this ear anymore. Not much in the other either. They say it's the wood. It isn't the wood: they made me ring the real one once, to see if I could take it."],
           opts: ["“What does it feel like when it rings?”", "“Stop practising. They're buying your ears.”", "“Practise with earplugs. Ask them to give you some.”", "Strike the wooden bell yourself"] },
      siente: { say: ["You don't hear it. You feel it in your teeth. And then a huge silence, as if someone had shut a door the size of the Meadow.",
                      "The pigeons left the courtyard that afternoon. They never came back."] },
      dejar: { say: ["And what do I do? My father was a lamplighter. When the lanterns went out, he sat at the door for ten years. I don't want to sit at the door.",
                     "But he leans the mallet against the wall.",
                     "No practice today. Today I listen. While I can still hear something."] },
      tapones: { say: ["Badajo goes to ask the House for earplugs. They give him beeswax and a pat on the back.",
                       "It works. A little. At least now I know my ears are worth something to someone. To you."] },
      golpear: { say: ["You take the mallet and strike the wood. It makes no sound. But your creature, on the ground, puts its paws over its ears, as if it had heard something you didn't.",
                       "It hears it. See? The wood rings too. For them it does."] },
    } },

    "e4-ambar": { who: { ambar: "Lady Ámbar" }, nodes: {
      a: { say: ["In a big Meadow house with bare walls, an old woman sits on the only chair left. Where paintings used to hang there are lighter marks on the paint. She is Cobre's mother.",
                 "I sold it all. The paintings, the rugs, the lantern at the entrance, the one from the Vigil. So my son can buy nights from a bell that doesn't ring yet.",
                 "My grandmother sold light. I sell what my grandmother bought with the light. In the end, Caretaker, the Houses only know how to sell. And buy. And call it tradition."],
           opts: ["“Do you agree with the Bell?”", "“Cobre painted a night for the Quarter.”", "“Your House could stop buying.”", "Ask her about the Vigil lantern"] },
      acuerdo: { say: ["I agree with my son eating. The Bell is the last thing that can be bought in the Glade. If we don't buy it, the Court will.",
                       "And if the Court has the nights, the Meadow ground opens when they want. That already happened. In another era, with another thing. It always happens."] },
      barrio: { say: ["Yes. He told me. He thought I'd die of the shock.",
                      "She laughs, quietly, without much heart.",
                      "It was the only thing he ever did in his life without asking me. That day I thought maybe my House doesn't end with him. Maybe something else begins."] },
      dejar: { say: ["Stop buying? And keep what?",
                     "She looks at the empty walls. The marks of the paintings.",
                     "You're right about one thing. There's nothing left to lose. That gives you a horrible kind of freedom. I'll talk to my son. I won't tell him what to do. I'll tell him he doesn't need to save me anymore."] },
      farol: { say: ["I sold it to the Guild. They melted it down. It was root glass, from when the Houses drew light from the wells.",
                     "Now it's part of the Bell, I suppose. My grandmother's light, made into a bell to put to sleep the Root that woke. Some things find their own way back to where they started."] },
    } },

    "e4-candela": { who: { candela: "Grandma Candela" }, nodes: {
      a: { say: ["On a corner of the Quarter, an old woman sells bread from a window. Her hands are covered in flour and her eyes are still quick. You recognise her by the way she counts coins in her palm: it's Candela, Aurelia's granddaughter.",
                 "Caretaker. It's Candela, remember? Still alive. Me too, look. Both things are strange.",
                 "My grandson works in the deep furnaces. His nails are grey. He tells me it's soot. I saw my grandmother say she knew nothing with the face of someone who knew everything. I know that face."],
           opts: ["“You read the notebook aloud, at the Trial.”", "“You drank a cup every moon, to see if your grandmother would open it.”", "“You defended your grandmother on every corner.”", "“What do you want to do about your grandson?”", "“Tell him about the statue in the Heart.”"] },
      leyo: { say: ["I read it and left. I left the surname on the stage. I've sold bread ever since. Nobody asks me which House I'm from.",
                    "My grandson doesn't know he's an Albor. Better. A surname is a debt they leave you."] },
      bebia: { say: ["Until the lake dried up. She never opened it. After death, same as before.",
                     "Now I see my grandson doing the same with his hands. Looking at them and not opening them. That gets passed down."] },
      defendia: { say: ["I shouted a lot. I don't shout anymore. My voice got tired before my anger did.",
                        "Grandmother knew. I knew too. That's why I shouted."] },
      nieto: { say: ["That he leave the furnaces. He doesn't listen. He says the Guild pays and I sell bread.",
                     "He's right. But bread doesn't turn you to stone."] },
      estatua: { say: ["You tell her about the third statue: the slag stuck to its base, just like on the workers' hands.",
                       "Candela closes the bread window. She shakes the flour off her hands.",
                       "My grandmother kept quiet and it cost the whole Quarter. I won't keep quiet. I'll tell my grandson, and every grandchild on this street. Let the Meadow know the Quarter knows things too."] },
    } },

    "e4-hundimiento": { who: { cerillo: "Cerillo" }, nodes: {
      a: { say: ["At dawn, on the edge of the Meadow, a house is missing. Where it stood there is a round, deep hole, its rim still smoking. Down below, a red glow.",
                 "Last night was a Court night on the board. The Root didn't sleep. The ground opened. The family got out through the window. The house didn't.",
                 "Around the hole, people from the Houses measure with ropes. Someone from the Court watches from afar, veil on. From the bottom of the hole come blows: someone is digging."],
           opts: ["“Who's digging down there?”", "Help the family that lost the house", "Go down into the hole", "Confront the one from the Court"] },
      quien: { say: ["Guild miners. They went down as soon as it opened. They say there are good veins under the Meadow houses.",
                     "On Court nights the ground opens, and the Guild digs. Nobody bought a night so the house wouldn't fall."] },
      familia: { say: ["You spend the day with the family: a mother, two kids and a grandfather who doesn't speak. You find them blankets, a roof at the Ford for a few nights, soup.",
                       "You didn't give them back the house. But you gave them a place that doesn't shake. That's a lot."] },
      bajar: { say: ["You climb down a rope. Down there it's as hot as a furnace. Three miners pick at a red vein that climbs the wall like a root.",
                     "One looks at you and pulls the cloth from his mouth. He has a young face and hands grey up to the wrist.",
                     "He says nothing. He goes back to digging. Up above, through the hole, there's a piece of sky in the shape of a house."] },
      corte: { say: ["You walk up to the one from the Court. She lifts her veil. A young woman, with dark circles under her eyes.",
                     "You tell her the night was theirs. That the house fell on their night.",
                     "She doesn't deny it. She gives you a coin, the only one in her hand, for the family.",
                     "“We bought the night so the ground would open under the Dawn Tower,” she says. “We didn't know where it would open. Nobody knows where it opens.”"] },
    } },

    "e4-subasta": { who: { cobre: "Cobre, of the Houses", badajo: "Badajo, bell-ringer of the Houses" }, nodes: {
      a: { say: ["In the Meadow square there's a stage and an auctioneer with a gavel. Up for auction is the first stroke of the great Bell, the night they hang it: whoever wins decides whether it rings or not.",
                 "The Houses pooled everything. Everything. The Court too. They're neck and neck. If we win, Badajo rings. If the Court wins, it doesn't ring, and that night the ground opens under the whole Meadow.",
                 "I don't know if I want to ring it. But if I do, at least I know where the ground won't open."],
           opts: ["“And if nobody wins?”", "Bid for the Ford", "Let the Court win", "Climb onto the stage and stop the auction"] },
      ninguno: { say: ["Then the stroke stays free. And the Guild decides. And the Guild sells the stroke to whoever pays most afterwards. So someone wins anyway."] },
      vado: { say: ["You raise your hand. The whole square turns to look at you. The auctioneer repeats your bid, which is small, and nobody understands it.",
                    "The Houses and the Court look at each other. Neither bids again. Both would rather the Ford have it than the other.",
                    "The Ford won. With nothing. Because nobody wanted the other side to win. That's how you win in the Glade.",
                    "Then I'm not ringing it. Fine. I'm a little glad."] },
      corte: { say: ["You do nothing. The bidding climbs. In the end the Court wins by one coin. The grey veils applaud in silence.",
                     "We lost. My House lost. That night the ground will open wherever the Court wants.",
                     "Badajo leaves the wooden mallet on the stage and walks off. He looks relieved, though he tries not to show it."] },
      parar: { say: ["You climb onto the stage. The auctioneer stares at you, gavel in the air. You speak loudly: the Root isn't for auction, the ground that opens doesn't choose an owner, the house that fell belonged to someone who bought nothing.",
                     "Some applaud. Many shout. The auctioneer lowers the gavel without striking.",
                     "You ruined it. Everything we saved. Well. You ruined it for the Court too.",
                     "The auction doesn't happen. The stroke stays in the hands of the Guild, which doesn't know what to do with it."] },
    } },

    "e4-escuela": { who: { pizarra: "Pizarra, teacher" }, nodes: {
      a: { say: ["In a Meadow school, twenty kids sitting on the floor recite the history of the Glade from memory. A teacher with chalk in her hair listens with her eyes closed.",
                 "Come in, Caretaker. The kids learn what happened. What the Chronicle says, at least. Now it's the Bell's turn: that the Guild will put the Root to sleep forever, and that this is progress.",
                 "The little ones ask me who used to sing to the Root. I don't know what to tell them. Do you?"],
           opts: ["“The Chronicle blames the Court. It's not the whole truth.”", "“The Houses paid for the blame by selling the forges.”", "“Nobody remembers the Line anymore. I do.”", "Tell the kids who used to sing", "Teach them the lullaby"] },
      farol: { say: ["I know. My grandmother was from the Court. I teach the Chronicle because otherwise they'd throw me out.",
                     "But to the Court kids I say, quietly, that their grandmother wasn't the only one. They look at me as if I'd given them a present."] },
      mareas: { say: ["Yes. And the Houses' kids know it. Some carry it like a shame, others like a war wound.",
                      "None of them knows that what they sold is what the Bell is made of now. That's in no book."] },
      espejo: { say: ["The Line? What Line?",
                      "You explain. She writes on the board while you talk, fast, so she won't forget.",
                      "This isn't written anywhere. Nobody knows it. If it's true, the Bell is a huge mistake. And nobody will see it coming."] },
      contar: { say: ["You tell the kids: that the Root used to sleep with a lullaby, that all the peoples had to come together to sing it, that it was hard and that's why it was worth it.",
                      "A little girl raises her hand. “So why don't we sing it now, instead of making a bell?”",
                      "Nobody answers. Pizarra writes the question on the board, in big letters, and doesn't erase it at the end of class.",
                      "Tomorrow I'll ask the Houses. The question is hers. I'm just carrying it."] },
      nana: { say: ["You sing the lullaby. The kids learn it in three rounds. In the end they sing it by themselves, off-key, loud.",
                    "Outside, in the street, someone passing by stops to listen. Then another.",
                    "It's not in the curriculum. But I'll sing it again tomorrow, in case they forget."] },
    } },
  });

  /* ---------- Warm Crater: the young masters, the casting, Chispa, Escoria and Tizón ---------- */
  add("crater", {
    "e4-maestros": { who: { fogarin: "Fogarín, Master of the Guild", fuelle: "Fuelle, young master" }, nodes: {
      a: { say: ["In the Guild masters' hall there's a long table with twelve chairs. Fogarín sits at the head. At the other end, a young master with strong arms and already grey nails bangs the table with his fist.",
                 "More deep furnaces! With ten more, the great Bell is done in a year. And with what's left over, we make tools the Glade has never seen!",
                 "With ten more, in a year we have four hundred more stone hands. Fuelle, look at your nails.",
                 "My nails are mine, Master. And the Guild belongs to those who work, not to those who remember the Tides."],
           opts: ["“Why the hurry, Fuelle?”", "Back Fogarín", "Back Fuelle", "“Let the workers vote, not the masters.”"] },
      prisa: { say: ["Because if we don't finish it, the Houses will, with our furnaces. Or the Court with its charcoal. The Bell has to belong to Fire.",
                     "All our lives they bought from us. For once, let them buy something from us that only we know how to make."] },
      fogarin: { say: ["You speak in favour of Fogarín. The old masters nod. The young ones eye you with distrust.",
                       "They vote: no new furnaces. Fuelle gets up and leaves, slamming the door.",
                       "Thank you. That boy will be Master someday. I hope with hands."] },
      fuelle: { say: ["You speak in favour of Fuelle. Fogarín looks at you with something close to sadness.",
                      "They vote: five new furnaces, not ten. Fuelle smiles as if he'd won everything.",
                      "Five. Fine. Five more furnaces is what Fire takes when nobody tells it no. Remember this day, Caretaker."] },
      votar: { say: ["The workers? The ones sitting on the floor with their arms crossed?",
                     "The ones who have the hands. Yes. Let them vote.",
                     "That afternoon four hundred workers vote in the Guild courtyard, with white and black stones in a bucket. Black wins: no new furnaces. Fuelle counts the stones twice.",
                     "Fine. I lost to my own people. That hurts differently."] },
    } },

    "e4-fundicion": { who: { yunque: "Yunque, smith" }, nodes: {
      a: { say: ["It's casting day. The root metal runs down the stone channel towards the enormous mould of the great Bell, red, slow, like a river that thinks. A hundred workers watch in silence.",
                 "Halfway along, the channel cracks. The metal starts spilling out one side, towards where the youngest workers stand. Yunque is closer than anyone.",
                 "Back! Everyone back!"],
           opts: ["Help Yunque plug the crack", "Get the young ones out of there", "Sing the lullaby to the metal"] },
      tapar: { say: ["You run with Yunque. He pushes his grey hand into the crack, the stone one, the one that no longer feels. The metal doesn't burn it. You shove a slab against the channel wall.",
                     "The crack closes. The metal flows on to the mould. Yunque pulls his hand out. Now the stone reaches his elbow.",
                     "It doesn't hurt. I told you. It just weighs more."] },
      jovenes: { say: ["You push the young workers back, shouting. The metal passes where they were and cools in a red puddle on the ground.",
                       "Yunque plugs the crack by himself, with his stone hand. When he's done, he looks at it the way you look at a broken tool.",
                       "Well done. They still have flesh hands. May they last."] },
      nana: { say: ["You don't know why you do it. You sing. The metal spilling from the crack grows slower, darker, as if it were listening.",
                    "Yunque takes the chance and plugs the crack. The rest of the metal reaches the mould unhurried.",
                    "What was that? The metal went still. Like an animal when you talk to it softly.",
                    "The workers look at you strangely for the rest of the day. Some hum the lullaby under their breath as they work."] },
    } },

    "e4-chispa2": { who: { chispa: "Chispa" }, nodes: {
      a: { say: ["On the south slope, behind her house, Chispa has built a forge from river stones and a bellows made from a leather bag. She's hammering something tiny.",
                 "Caretaker! Look. It's a nail. My first nail. It's crooked, but it's a nail.",
                 "She shows you her hand. The little grey spot on her fingertip has grown. Now it covers the whole nail."],
           opts: ["“What metal did you make it with?”", "“Tizón taught you to forge cold.”", "“I gave you that hammer.”", "Take her to dip her hand in Forest resin", "“Keep going. You're doing well.”"] },
      metal: { say: ["River iron, mostly. And a tiny bit of red. From an ingot that fell off a cart. Just a tiny bit, so it holds.",
                     "With the tiny bit of red the iron gets good. It bends and doesn't break. Don't tell anyone."] },
      frio: { say: ["Yes. It's boring. It takes three times as long. But the master says whoever forges cold still has hands at a hundred. Like him.",
                    "I made this nail cold. Nothing red. That's why it's crooked. But it's all mine."] },
      martillo: { say: ["Yes! I use it every day. It already has a dent in the shape of my hand.",
                        "When I grow up, I'm going to make you one. Better than this."] },
      resina: { say: ["You take her to the Forest. Hacha lets her dip her hand in a bucket of resin from an old tree.",
                      "When she pulls it out, the nail is still grey. But the fingertip bends again.",
                      "It moves. It moves! Okay. I won't use red anymore. I swear. At least until I grow up."] },
      sigue: { say: ["Really? For real?",
                     "She starts hammering harder, happy. The little grey spot glints a bit in the fire.",
                     "You leave. From the slope you can still hear the hammer, small, stubborn."] },
    } },

    "e4-escoria": { who: { escoria: "Escoria, worker" }, nodes: {
      a: { say: ["Escoria sits on the Guild steps, alone, hands in her lap. She doesn't shout anymore. Her voice is hoarse from doing it so much.",
                 "Come to see how it ended? Sit down."],
           opts: ["“The deep furnaces closed because of the strike.”", "“Half went back to work for Cobre's purse.”", "“The short-shift deal was signed.”", "“And your hands?”"] },
      huelga: { say: ["They closed for a week. Then the Guild brought people from outside, from the south slope, people who didn't know. Now the kids from the slope have grey hands, and we have no work.",
                      "We won. That's how you win: you pass the problem to someone poorer."] },
      recado: { say: ["Half. Now half have a purse and grey hands. The other half, nothing. And both sides hate me: some for not taking the purse, others for making them feel it was wrong to take it.",
                      "Cobre sent me a letter asking for forgiveness. I used it to light the fire."] },
      mediar: { say: ["One-hour shifts. It works. Hands go grey more slowly. More slowly isn't never.",
                      "But look: last week someone broke a foreman's hand because he made him stay two hours. Before, nothing got broken. Now there's a paper to break."] },
      manos: { say: ["Escoria raises her hands. They're grey up to the wrist. The fingers bend, but slowly, as if they think before moving.",
                     "Still. But not for long. When I can't move them anymore, I want someone to remember why. I don't want a statue. I want them to remember."],
               opts: ["“I'll remember.”", "“Write it down. Let the Hollow keep it in stone.”", "“Go to the Heart. Let the nine peoples see it.”"] },
      acordar: { say: ["You. Well. You remember things from sixty years ago. That's what they say.",
                       "She takes your hand in hers, hard and warm. She doesn't squeeze. She can't squeeze much."] },
      escribir: { say: ["Escoria dictates. You write. The names of the grey-handed workers, the shifts, the hours, what happened with the strike.",
                        "Galena takes it to the Caves and carves it on a new wall, far from the others. A wall of hands.",
                        "There. In stone. Which is what's going to happen to all of us. At least let it say who we were."] },
      corazon: { say: ["To the Heart? To beg?",
                       "She stares at her hands for a long while.",
                       "Not to beg. To show. If the nine peoples come together, the Quarter will go with these hands raised. So nobody can say they didn't know."] },
    } },

    "e4-tizon": { who: { tizon: "Master Tizón" }, nodes: {
      a: { say: ["Master Tizón is in bed. There's a pile of coins on the blanket, sorted by size. He breathes slowly, with a whistle. When he sees you, he smiles with half his mouth.",
                 "You came. Good. I'm dying. Don't make that face: I'm a hundred and twelve and I counted these coins twice every day of my life. It was about time.",
                 "I don't know who to leave them to. The Guild, which was my life. Or someone who isn't Guild. You decide. I've decided too much already."],
           opts: ["“Why did you count them twice?”", "“Leave them to the Guild.”", "“Leave them to Chispa.”", "“Leave them to the grey-handed workers.”"] },
      dos: { say: ["Because the first time you count what you have. The second, what it cost you to have it.",
                   "It never came out the same. Not once in a hundred years."] },
      gremio: { say: ["The Guild. Yes. Let it outlive me. It's the only thing I ever wanted.",
                      "He closes his eyes. Fogarín arrives that night and sits beside the bed until morning. He doesn't count the coins."] },
      chispa: { say: ["The girl from the slope. Yes. The one who forges cold because I asked her to.",
                      "He gives you the coins wrapped in a rag. They weigh more than they look.",
                      "Tell her not to count them. Or to count them once. Don't let her learn my habit. Let her learn the other one.",
                      "He dies at dawn. Chispa receives the rag and cries for an hour without opening it."] },
      obreros: { say: ["Tizón looks at you for a long time. Then he nods, slowly.",
                       "All my life I paid them what was fair. Fair by my count. Let them keep it. For resin, for food, for whatever they lack when they can't close their fists anymore.",
                       "He dies that night. The coins are handed out in the Guild courtyard, one per worker. Escoria counts hers twice and laughs, crying."] },
    } },
  });

  /* ---------- Deep Forest: the Council, the clearing, the last old tree and the fire ---------- */
  add("forest", {
    "e4-musgo": { who: { musgo: "Musgo, of the Council" }, nodes: {
      a: { say: ["In the Council house, seven elders argue about whether they're allowed to argue. A man with a greenish beard presides from a chair of roots. Every so often someone says “no” and everyone nods.",
                 "The Council banned logging. A year ago. The woodcutters keep logging. The Council banned selling wood to the Guild. They keep selling. The Council banned talking about this. And here we are.",
                 "We know how to say no. It's the only thing we know. We don't know what to do when nobody listens to the no."],
           opts: ["“Stop banning and pay for looking after it.”", "“Talk to Hacha. She plants three for one.”", "“Ban it harder. Post guards.”", "“What did the Council say before it learned to say no?”"] },
      pagar: { say: ["Pay? The Council has no coins. It has moss, mushrooms and years.",
                     "One of the elders raises a hand. He says they have seeds. The oldest in the Glade. Worth more than wood, if someone knows how to use them.",
                     "Seeds for trees left standing. It's an idea. A strange idea. It's not a no. It's been a long time since the Council had an idea that wasn't a no."] },
      hacha: { say: ["The woodcutter? The one who cuts?",
                     "You tell them about the three for one. The seven elders look at each other.",
                     "Then the one who cuts cares for it more than the Council. I don't like that. But it's true. Let Hacha come to the next session. With her axe, if she wants. The Forest will go to the Heart with the one who cuts and the one who doesn't."] },
      guardias: { say: ["The Council sends twelve young people with sticks to guard the old trees. Within a week, six have gone over to the woodcutters. The Guild pays them more.",
                        "You see. A no with a stick is a no that can be bought."] },
      antes: { say: ["Before it learned to say no... it said “wait”. That's what the records say. “Wait for it to grow.” “Wait and see.”",
                     "I think some old Council got tired of waiting, and learned the no. Faster. Worse."] },
    } },

    "e4-claro": { who: {}, nodes: {
      a: { say: ["Where there used to be a dense forest, there's now a huge clearing full of stumps. The sun pours straight in. It's hot. The moss on the stones has dried and falls off in pieces.",
                 "No birds can be heard. The Forest creatures have gone deeper in, where there's still shade. Your creature presses against your legs, eyes squinting in the light.",
                 "At the edge of the clearing, a tiny Forest creature, alone, circles a stump. It's looking for something that's no longer there."],
           opts: ["Go up to the creature by the stump", "Plant something in the clearing", "Keep going towards the shade"] },
      criatura: { say: ["You crouch. The creature looks at you and doesn't run. In the stump there's a hollow, and in the hollow, the remains of a nest.",
                        "Your creature approaches slowly and touches its nose with its own. The two stay still a while.",
                        "In the end the tiny creature follows you to the shade, a few steps behind, coming no closer. That night it sleeps near the campfire."] },
      plantar: { say: ["With your hands you dig a hole in the dry earth and bury a seed you'd been carrying in your pocket since who knows when. You water it from your canteen.",
                       "It won't grow. It's too hot, the soil is full of ash. You know it. You plant it anyway.",
                       "Your creature sits beside the hole. When you leave, it stays a while longer, as if waiting for something."] },
      seguir: { say: ["You cross the clearing quickly, without looking. In the shade on the other side the air is cool, and smells of leaves. A bird can be heard, far off.",
                      "Behind you, the clearing shines like an empty plate."] },
    } },

    "e4-carboneros": { who: { hacha: "Hacha, woodcutter", hulla: "Hulla, Court charcoal burner" }, nodes: {
      a: { say: ["At the border between the Forest and the Hollow, two groups glare at each other. On one side, woodcutters with axes. On the other, Court people with veils and black shovels.",
                 "The Court sells charcoal to the Guild cheaper than our wood. If they keep it up, we're out of work. And the Forest gets cut anyway, because the Court cuts too: here, at night, and burns it in the Hollow.",
                 "We cut what you leave lying around. Branches, stumps. Whole trees, you cut those. Don't come saying the Forest is yours because you kill it first."],
           opts: ["“Why fight each other and not the Guild?”", "Propose they work together: wood and charcoal, one price", "Take Hacha's side", "Take Hulla's side"] },
      gremio: { say: ["Because you can't hit the Guild. It's far away, it has furnaces, it pays.",
                      "And each other, we can. It's always easier to fight someone who's as stuck as you are.",
                      "They look at each other. For a moment, they almost laugh."] },
      juntos: { say: ["You propose a deal: one price for wood and charcoal, paid by the Guild equally to both. And that neither cuts living trees over a hundred years old.",
                      "With the Court? My grandmother would rise from her grave.",
                      "Mine too. Maybe they'll meet on the way and come to an agreement.",
                      "They sign with earth on their fingers, on a stone. The price reaches the Guild the next day. Fogarín accepts it without haggling. He says it was about time someone agreed on something."] },
      hacha: { say: ["You side with the woodcutters. The Court backs away, slowly, towards the Hollow.",
                     "Fine. Now we know whose side the Ford is on. Always the side with more people.",
                     "That night three axes vanish from Hacha's camp. Nobody saw anything."] },
      hulla: { say: ["You side with the Court. The woodcutters glare at you.",
                     "The Court. Of course. The one that always has an excuse. Enjoy the charcoal.",
                     "The next day the Guild stops buying wood. It only buys charcoal. Twelve woodcutter families go without income that month."] },
    } },

    "e4-retono": { who: { retono: "Retoño, of the Council" }, nodes: {
      a: { say: ["On the shore of the Forest lake, a grey-haired man with a stainless mouth sits on a small chair someone brought out of the Council house. He's looking at the stumps on the far shore.",
                 "Caretaker. It's Retoño. Years have passed. I was the boy with the purple mouth, remember? Now the mouth is clean and the Forest is cut. I don't know which is worse.",
                 "The Forest's young people don't go to the lake to drink visions anymore. They go to the Crater to work. They come back with grey hands. There's always something the young go looking for outside, and it always costs them something."],
           opts: ["“You speak for the young in the Council.”", "“You stayed on the shore counting the ones who came back.”", "“You went down to the shore with the Council elders.”", "“What would it take for them to stay?”", "“Go to the Crater and bring them back.”"] },
      concejo: { say: ["I speak. The second thing I was going to ask for, I never said. I don't remember what it was anymore. I think it was “that you can come back”.",
                       "Now I'd ask for it. That you can come back from the Crater with your hands whole."] },
      orilla: { say: ["I used to count them. Now I count the ones who come back from the Crater. More of them come back. But they come back different.",
                      "The small chair is still empty in the Council. I took it out to look at the water. Nobody claimed it."] },
      viejos: { say: ["We'd go down. We'd talk until the sun came up. Now the elders of back then are dead and the elders of now are us.",
                      "Tomorrow I'm going down with the young ones from the Crater. Let's see if talking fixes something. It didn't fix anything before. But we got to know each other."] },
      quedar: { say: ["Work. Something that pays and doesn't turn you to stone or take your memories. The Forest never paid for being looked after. That's the same old problem.",
                      "If the Council paid with seeds, with land, with something... The young don't want coins. They want something of their own."] },
      traer: { say: ["Retoño gets up from the small chair slowly. He leaves for the Crater that same afternoon, on foot.",
                     "He comes back a week later with eight young people from the Forest. Their nails are grey. One, the whole hand.",
                     "Eight out of forty. The others said no. That the Guild pays and the Forest doesn't. They're right. But these eight are going to plant the three for one. It's something."] },
    } },

    "e4-semillas": { who: { hacha: "Hacha, woodcutter" }, nodes: {
      a: { say: ["In the clearing of stumps there are rows of planted saplings. Hundreds of them, with little sticks beside them so they don't fall over. Half are yellow. Some, black at the tip.",
                 "The soil is full of furnace ash. And hot from below. The saplings can't take it. We plant three for one and two die.",
                 "An old tree takes three hundred years. A sapling dies in a month. The numbers don't add up, Caretaker. They never did."],
           opts: ["“Why is the ground hot?”", "Water them with the cold water from the Deep", "Plant in the shade, further in", "“Plant anyway. Some will hold.”"] },
      caliente: { say: ["The veins. The miners say there are red veins running under the Forest, towards the Heart. They heat everything from below.",
                        "The Forest is cooking from the bottom up. And we're planting on top."] },
      fria: { say: ["Témpano sends two barrels of cold meltwater. They water a whole row of saplings.",
                    "A week later, that row is green. The others aren't.",
                    "The cold of the Deep saves the Forest. But only one row. And the cold water doesn't come back. That's how it always is: enough for one row."] },
      sombra: { say: ["They transplant the remaining saplings further in, into the shade of the trees still standing. It takes days.",
                      "They last longer there. But there the old trees steal their light. As always. The old don't let the new grow, and if you cut them, the new ones cook."] },
      igual: { say: ["Plant anyway. Yes. That's what my grandmother did. She planted even when she knew.",
                     "They keep planting. By the end of the season, of a hundred saplings eleven remain. Hacha counts them the way you count children."] },
    } },

    "e4-arbolviejo": { who: { hacha: "Hacha, woodcutter", musgo: "Musgo, of the Council", escoria: "Escoria, worker" }, nodes: {
      a: { say: ["At the centre of the Forest stands one enormous tree, the oldest, the one the Council calls the Mother. Around it are three people who aren't speaking to each other.",
                 "Its resin alone is enough for a hundred workers for a year. A hundred pairs of hands that bend again.",
                 "Its wood is enough for the Guild to stop buying firewood for three winters. Twelve families eat for three years.",
                 "And it's the Mother. The seeds of the whole Forest come from her. If they cut her, the Forest doesn't come back. Ever."],
           opts: ["“Is there no other way to get resin from it?”", "“Cut it. Hands first.”", "“Bleed it little by little, without cutting it.”", "“Nobody touches it.”"] },
      otra: { say: ["Bleed it. Make small cuts in the bark and collect what drips. It takes years. It weakens her. But she lives.",
                    "Years. My hands don't have years."] },
      cortar: { say: ["It takes two days to cut her down. She falls with a sound heard all the way to the Meadow. The Forest goes silent.",
                      "The resin goes in barrels to the Crater. A hundred workers dip their hands. They come out soft. Escoria cries in front of everyone.",
                      "There. The Mother heals hands. Let them remember that when the Forest doesn't come back."] },
      sangrar: { say: ["They make twelve small cuts in the bark, like open veins. The resin drips slowly into buckets. One bucket a moon.",
                       "One bucket a moon. Twelve hands a moon. Fine. Twelve is more than none.",
                       "And the Mother is still standing. Wounded, but standing. Like everyone here."] },
      nadie: { say: ["Nobody? You're going to look at my hands when they don't move anymore and tell me it was worth it for a tree?",
                     "You have no answer that would help her. Musgo puts his hand on the Mother's bark.",
                     "Thank you. The Forest won't forget it. Neither will Escoria. Both things are true."] },
    } },

    "e4-incendio": { who: { hacha: "Hacha, woodcutter" }, nodes: {
      a: { say: ["At dusk smoke rises from the edge of the Forest, where the metal carts' road runs. An ingot fell from a cart and set the dry leaf litter alight. The fire is moving towards the new saplings.",
                 "Water! Earth! Anything!",
                 "The woodcutters run with buckets. It isn't enough. The fire is red, too red, and water won't put it out: the ingot in the middle keeps burning."],
           opts: ["Dig a trench to cut off the fire", "Pull the ingot out of the middle of the fire", "Save the saplings, even if the rest burns"] },
      zanja: { say: ["With the woodcutters you dig a wide trench between the fire and the old Forest. It takes all night. The fire reaches the trench and stops.",
                     "On the other side everything is black: the saplings, the stumps, the road. The old Forest, on this side, untouched.",
                     "We saved the old. The new burned. It's always like that when you have to choose fast."] },
      lingote: { say: ["You cover yourself with a wet blanket and go in. The heat is so strong you can't breathe. You grab the ingot with two green branches and drag it to the stream.",
                       "When it falls in the water, the stream boils and gives off a red steam. Without the ingot, the fire weakens. The buckets are enough.",
                       "Have you lost your mind? Well. Thank you. Look at your hands.",
                       "Your palms are red. And on one, a little grey spot the size of a lentil."] },
      brotes: { say: ["You run to the saplings with the youngest woodcutters. They pull up what they can, soil and all, and carry them to the stream in their arms.",
                      "They save forty. The rest of the clearing burns. The fire reaches the edge of the old Forest and burns three trees before they stop it.",
                      "Forty saplings for three old trees. I don't know if it's a good trade. But we chose the saplings."] },
    } },
  });

  /* ==================== Delivery 3: the Night (Shadow Hollow, Mirror Lake, Echo Caves) ==================== */

  /* ---------- Shadow Hollow: the charcoal kilns, the king's tomb, the Queen and the veils ---------- */
  add("hollow", {
    "e4-hornos": { who: { hulla: "Hulla, Court charcoal burner" }, nodes: {
      a: { say: ["Under the Hollow there are galleries that used to be vision cellars. Now they're kilns: mountains of wood covered with earth, burning slowly, without flame. The air is thick and sweet. It's hard to breathe.",
                 "A line of veiled charcoal burners comes out of a gallery, coughing. One falls to his knees. The others lift him up without stopping coughing.",
                 "Shadow charcoal doesn't give off smoke outside. It gives it off inside. It stays in the galleries, in the lungs. That's why it can't be seen from above. That's why they buy it."],
           opts: ["“How long does a charcoal burner last down here?”", "Dig chimneys, even if the smoke can be seen from above", "Bring moss from the Forest to filter the air", "Put out the deepest kiln"] },
      cuanto: { say: ["Ten years, if they start young. Then they cough until they forget how to breathe.",
                      "The Crater's hands can be seen. The Hollow's lungs can't. That's why nobody strikes down here."] },
      chimeneas: { say: ["With the charcoal burners you dig three narrow chimneys up to the surface. It takes a week. The smoke finally comes out, grey, and hangs over the Hollow like a roof.",
                         "It can be seen from the Meadow. The next day, the Houses ask. The day after, the whole Glade knows who heats the Bell.",
                         "We breathe. And they look at us. Both at once. I suppose you can't have one without the other."] },
      musgo: { say: ["You bring sacks of damp moss from the Forest. The charcoal burners tie it over their mouths, under the veil. It smells of wet earth.",
                     "It works. I cough less. The woodcutters charge us for the moss, of course. Everything gets charged. But they charge cheap.",
                     "For the first time in years, someone from the Court and someone from the Forest make a deal without fighting."] },
      apagar: { say: ["You pour water on the deepest kiln until the earth stops smoking. A black steam rises that makes your eyes water.",
                      "That kiln gave a month's charcoal. The Guild will pay less. Some will eat less.",
                      "But the one who worked there was my nephew. So thank you. And don't do it again without asking."] },
    } },

    "e4-tumba": { who: { onix: "Ónix, keeper of the tombs" }, nodes: {
      a: { say: ["In the Court cemetery, among black headstones, a young keeper sweeps the leaves with a broom of twigs. He stops in front of a tomb bigger than the others, with a carved crown and worn stone.",
                 "My name is Ónix. I look after the Court's dead. This is King Lóbrego. He died sixty years ago. You knew him, they say.",
                 "Kids come at night to write things on it. I erase them by day. I'm not sure why. They pay me to erase."],
           opts: ["“What does the tomb say?”", "“He said at the Trial that he didn't ask.”", "“He used to leave the Throne door open.”", "“His cup is still untouched in the cellar.”", "“Don't erase what they write.”"] },
      dice: { say: ["“King”. Nothing else. And below, what the kids write. Last night they wrote: “He sold the night and bought charcoal”.",
                    "It isn't true. The charcoal is from now. But kids mix up the dead. To them all kings are the same one."] },
      nopregunto: { say: ["Yes. “Who didn't ask”. That's carved. Someone carved it with a nail, deep, long ago. It can't be erased.",
                          "Sometimes I think the whole Court should have that on its door. That it doesn't ask. That it never asks where what it sells comes from."] },
      puerta: { say: ["The Throne door is still open. Nobody shut it when he died. Queen Merma goes in and out through it every day.",
                      "Nobody asks her anything. An open door is no use if nobody goes in to ask."] },
      copa: { say: ["The cup. Yes. I look after the cellar too. It has sixty years of dust. Nobody dares throw it out or drink it.",
                    "Sometimes I look at it and think everything the king didn't want to know is in there. And that the Court still doesn't."] },
      noborrar: { say: ["And if they throw me out?",
                        "He looks at the tomb. He looks at the broom.",
                        "Fine. I'll leave one. The one that says something true. Lies I erase, truths I leave. That way at least erasing is good for something.",
                        "That night, someone writes on the stone: “The Court heats the Bell”. Ónix doesn't erase it."] },
    } },

    "e4-bruna": { who: { bruna: "Old Bruna" }, nodes: {
      a: { say: ["In a low house in the Hollow, an old woman knits beside a lamp. She doesn't look at the knitting. She looks at the shadows the lamp casts on the wall.",
                 "Caretaker. It's Bruna, remember? The girl with the shadow. Now I'm the old woman with the shadow. Come in.",
                 "Look at the charcoal burners' shadows when they pass the door. They're stiff. They don't bend when the people bend. As if they were stone. I know about shadows."],
           opts: ["“You walk with a shadow made of mist.”", "“You used to sing the lullaby to the sun.”", "“You don't look for your shadow anymore.”", "“What's happening to the shadows?”", "“Teach them to look after their shadows.”"] },
      niebla: { say: ["Calina's. I still have it. It's worn, full of holes, like an old blanket. Calina died long ago. The shadow didn't.",
                      "With this shadow I see the others. That's how I know they're stiff. Woven shadows know when another one is sick."] },
      sol: { say: ["Every day. Sixty years. The pale thing that followed me is still there. Paler. You can hardly see it now.",
                   "But now it follows the charcoal burners too, when I sing to them. A little. As if it were lending them something."] },
      sinsombra: { say: ["I don't look for it. But I see other people's. When you have none, you look hard at the ones others have.",
                         "And the charcoal burners' are getting like mine before it left. Still. First they go still."] },
      pasa: { say: ["Shadow charcoal smoke is made of burnt shadow. When you breathe it, the trees' shadow gets inside you. And yours goes stiff to make room for it.",
                    "Same as the Crater's hands. The metal goes in, the flesh turns to stone. Here the smoke goes in, the shadow turns to stone. It's always the same thing, just in another part of the body."] },
      ensenar: { say: ["Bruna gathers ten young charcoal burners in her house. She teaches them to move their hands in front of the lamp, slowly, watching the shadow, until the shadow bends again.",
                       "It's a children's game. My mother taught it to me. But if the shadow bends again, there's still time.",
                       "By the end of the night, three of the ten have soft shadows again. The other seven don't. Bruna writes them down on a piece of paper.",
                       "I'm going to the Heart with this paper and with my shadow. So the Hollow doesn't go with only charcoal."] },
    } },

    "e4-reina": { who: { merma: "Queen Merma" }, nodes: {
      a: { say: ["On the Throne of the Hollow, a middle-aged woman with no crown signs papers one after another. She has ink on her fingers and the shadows of many nights under her eyes. Behind her, the Throne door is open.",
                 "Caretaker. I'm Merma. Queen, they say. Bookkeeper, more like. The Court has more debts than veils.",
                 "I sell charcoal to the Guild, I buy nights on the board, and with those nights the ground opens under the Dawn Tower. Do you know why? Because under the Tower there's more metal than in the whole Crater. And it's the first time in a thousand years the Court can have something the Houses don't."],
           opts: ["“Because of your night a house in the Quarter fell.”", "“One of your guards gave a coin to the family.”", "“And if the Tower falls?”", "“Sell the metal, but don't let the ground open where people live.”", "“If you don't stop, I'll tell the whole Glade.”"] },
      casa: { say: ["I know. The ground didn't open where we asked. It opened where it wanted.",
                    "She puts down the pen. For the first time she looks straight at you.",
                    "I paid for the house. Twice over. The family didn't want the coins. They left them at the Throne door. They're still there, on the floor. I step on them every morning."] },
      moneda: { say: ["Yes. Tiniebla is her name. I punished her for giving it without permission. Then I raised her pay, without telling anyone.",
                      "That's how you rule here: you punish what's right in public, and reward it in secret. Don't ask me to like it."] },
      torre: { say: ["Then the Houses lose their Tower. And the Court, for once, isn't to blame: it was the ground.",
                     "That's what the part of me that's Queen tells me. The other part, the one that counts, knows the Tower has three hundred people inside."] },
      acuerdo: { say: ["Choose where it opens? Nobody knows how to choose where it opens.",
                       "You tell her about Galena's veins, the map, how they all run towards the Heart. Merma listens with her head tilted, like someone adding up.",
                       "Then I don't buy nights for the Tower. I buy nights for the empty lands to the north, where the veins pass. Less metal. Nobody underneath.",
                       "The Court will be a little poorer. And a little less hated. I don't know which of the two costs me more."] },
      contar: { say: ["Tell them. They'll believe you. You have sixty years of good name, I have a thousand years of bad.",
                      "She gets up, slowly, and walks you to the open door.",
                      "But before you tell them, ask yourself who buys the ground if the Court doesn't. Tomorrow the Glade hates me a little more. And the day after, the Houses dig under the Hollow."] },
    } },

    "e4-lista": { who: { ebano: "Ébano, Court archivist" }, nodes: {
      a: { say: ["Ébano waits for you in the archive with the lamp turned low. On the table there's another parchment, longer than the first, unrolled with weights on the corners.",
                 "I found the second sheet. The list didn't end at the crossed-out name. It goes on. Forty-one more names. The workers of the first forges.",
                 "Next to each name there's a mark. A tiny hand, drawn. Some of the hands are filled in with grey ink. Thirty-nine out of forty-one."],
           opts: ["“What do the grey hands mean?”", "“Find out if any of them have family today.”", "“Give the list to Escoria.”", "“Have it carved on the wall in the Caves.”"] },
      manos: { say: ["That their hands went. Thirty-nine out of forty-one. And the two left blank have another word beside them: “left”.",
                     "It doesn't say where. I suppose two people out of forty-one realised in time. The Guild didn't keep how."] },
      familia: { say: ["Ébano spends three days cross-checking the list against the birth records. He finds surnames. One repeats: it's Fogarín's surname.",
                       "The Guild Master's grandfather's grandfather is on the list. With a grey hand.",
                       "You take the sheet to the Crater. Fogarín reads it sitting on a cold anvil. He says nothing. That night he doesn't go down to the deep furnaces."] },
      escoria: { say: ["Escoria reads the list on the Guild steps, out loud, name by name, to anyone who'll listen. A crowd gathers.",
                       "When she reaches the end, someone shouts: “And the two who left? How did they leave?” Nobody knows.",
                       "From that day, in the Crater people say “leave” instead of “quit”. The foremen hate it."] },
      pared: { say: ["Galena carves the forty-two names on the wall of the Caves, with a tiny hand beside each one. It takes a month.",
                     "Now it's in stone. The Court kept it on paper a thousand years and hid it. The Hondura puts it in stone in a month and leaves it in plain sight. Every people keeps things the way it knows how."] },
    } },

    "e4-humo": { who: { hulla: "Hulla, Court charcoal burner" }, nodes: {
      a: { say: ["At midnight there are screams in the Hollow. A gallery of kilns has collapsed and the shadow charcoal smoke is rising through the old cellars into the houses. Black, thick, sweet.",
                 "People come out into the street coughing. There are kids with red eyes. A dog runs in circles. The lamps give no light: the smoke eats it.",
                 "We have to get the smoke out or get the people out! There isn't enough for both!"],
           opts: ["Break open the cellars' old chimneys so the smoke escapes", "Take everyone to the Ford", "Go down into the collapsed gallery for the ones left inside"] },
      romper: { say: ["With a crowbar you break the stone plugs of the old chimneys, the ones from when the Court made visions. The smoke starts to rise, slowly.",
                      "It rises so much that at dawn the Glade's sky is grey. In the Meadow the sun doesn't come out until noon.",
                      "The Hollow breathes. The Meadow can't see the sun. Tomorrow they'll blame us for the night. This time they're right."] },
      vado: { say: ["You lead the people along the river road to the Ford. Hundreds of them. They arrive at dawn, coughing, with blankets, with kids asleep in their arms.",
                    "The Ford fills up. Water, bread and floor have to be shared. Some Ford neighbours don't open their doors.",
                    "The ones who opened will remember. The ones who didn't, too. The Hollow has a good memory for doors."] },
      bajar: { say: ["You tie a wet rag over your face and go down. You can't see anything. You find two charcoal burners by their coughing, slumped against a wall. You drag them out one at a time.",
                     "When you come up with the second, you can't stop coughing. Hulla holds your head.",
                     "Two. You got two out. There were three. The third was my nephew.",
                     "She says nothing more. She gives you water. She sits beside you until you stop coughing."] },
    } },

    "e4-velos": { who: { merma: "Queen Merma", hulla: "Hulla, Court charcoal burner" }, nodes: {
      a: { say: ["In the Throne courtyard, the whole Court has gathered. Veils of every grey. The news has come: the peoples are gathering in the Heart over the Bell. The Court must decide whether to go.",
                 "If we go, they'll look at us. They'll blame us for the smoke, the ground, the house in the Quarter. And for things from a thousand years ago.",
                 "If we don't go, they blame us anyway. But we're not there to say what we know."],
           opts: ["“Go without veils.”", "“Go with veils. It's what you are.”", "“Don't send the Queen. Send the charcoal burners.”", "“Don't go. Not this time.”"] },
      sinvelo: { say: ["Without veils? In front of the Houses?",
                       "Hulla takes off her veil first. Then Ónix, the keeper of the tombs. Then an old woman. Then everyone, one by one, until the courtyard is full of faces.",
                       "Fine. If they're going to look at us, let them see the faces of the ones who cough. We go to the Heart like this."] },
      convelo: { say: ["With veils. Yes. A thousand years of veils aren't thrown away in one night.",
                       "A thousand years of veils and nobody knows our faces. Not even us.",
                       "The Court goes to the Heart veiled. They look at it anyway. Nobody knows whom to look at."] },
      carboneros: { say: ["The Court going without its Queen? That has never happened.",
                          "That's why. Let the one who breathes the smoke go. You sign. We cough.",
                          "Merma is silent for a long while. Then she nods.",
                          "Go, Hulla. And tell everything. The charcoal, the Tower, me. If the Court is truly going, let it go whole."] },
      novan: { say: ["The Court stays. Nobody from the Hollow goes to the Heart.",
                     "That's it. Our backs turned again. Let them say what they want about us. They always do."] },
    } },
  });

  /* ---------- Mirror Lake: Remanso, the baths, the fish, the shore you read and the water that dries up ---------- */
  add("lake", {
    "e4-remanso": { who: { remanso: "Remanso, the old seer" }, nodes: {
      a: { say: ["On the north shore, an old man with white hair and pale eyes sits on a rotten jetty with his feet in the water. He watches the steam rising from the south shore.",
                 "Caretaker. It's Remanso. The boy on the jetty. Now I'm the old man on the jetty. The jetty's the same, more rotten.",
                 "The hot water brings visions again. You don't have to drink it: the steam is enough. People stand on the south shore and breathe. And they see things."],
           opts: ["“You stopped drinking and fish in the river.”", "“You saw your father in the lake.”", "“You drank for those who paid.”", "“What do they see in the steam?”", "“Warn people not to breathe that steam.”"] },
      rio: { say: ["I fish in the river. The river doesn't boil, yet. But the river fish have a grey stripe on their backs. Like a hand.",
                   "I left the lake so I wouldn't see things. Now things come to the river."] },
      padre: { say: ["I saw him. And I kept drinking. That's why my eyes are like this.",
                     "Now in the steam I see something else. I see a man working at a forge under the water. I see his hands. They go grey as he hammers. He doesn't stop."] },
      pagaban: { say: ["I used to. I can't anymore: my hands shake and I drop the cup. Now I breathe the steam for free, like everyone.",
                       "I don't remember how old I am. But I remember what I saw last night: a bell that rings and a land that goes quiet all at once. And then, nothing. A silence with no bottom."] },
      ven: { say: ["Everyone sees something different. But in the end they all see the same thing: a sound you can't hear and something very big that stops moving.",
                   "The Guild folk say it's the Bell working. That it's a good omen. I've seen many omens. The good ones look a lot like the bad ones, from far away."] },
      avisar: { say: ["Remanso gets up from the jetty, with effort. He walks to the south shore leaning on your arm. He stands between the people and the steam.",
                      "I drank visions all my life. Look at my eyes. Don't breathe this. What you see isn't the future. It's what the lake doesn't want to happen.",
                      "Some leave. Others stay, breathing. Remanso stays with them, standing, so they can see him."] },
    } },

    "e4-banos": { who: { nacar: "Nácar, of the Houses", salitre: "Salitre, fisher" }, nodes: {
      a: { say: ["On the south shore, where the water boils less, the Houses have built white wooden baths, with awnings and steps. A sign says: “Waters of the Dawn. Health and rest”. There's a queue.",
                 "Welcome, Caretaker. Natural hot water. It cures coughs, cold, sorrows. One coin an hour. Half for the Houses.",
                 "Beside the baths, behind a fence, Salitre cleans cooked fish in a bucket. She doesn't look at the awnings."],
           opts: ["“Why can't the Tides go in?”", "“Let the furnace workers in for free.”", "“Let part of what you charge go to the Tides.”", "Break the fence"] },
      mareas: { say: ["They can go in. Paying. Like everyone.",
                      "Paying to bathe in the lake that was ours. That boils because the Guild digs. That the Houses charge for because they got here first with planks."] },
      gratis: { say: ["Free? For the workers? They dirty the water with soot.",
                      "You tell her the hot water softens grey hands a little. That you've seen it. Nácar hesitates.",
                      "One hour a week. Tuesdays, early, before the Houses arrive. That's what I can do.",
                      "The next Tuesday there are a hundred workers in the queue, in the dark. They come out with red hands, a little softer."] },
      parte: { say: ["A part? Of what?",
                     "Of what you charge for our water.",
                     "Nácar looks at the queue. She looks at Salitre. She works it out under her breath.",
                     "A tenth. Not one coin more. And let it be known it's a gift from the Houses.",
                     "A gift. With our water. Fine. I accept. And I'm writing it down."] },
      cerca: { say: ["You pull two planks off the fence. Salitre looks at you. Then she pulls off the third.",
                     "The Tides go into the baths without paying, feet covered in mud. The Houses folk leave, offended. Nácar shouts.",
                     "The next day there's a new fence, taller, and a guard. And a new sign: “No entry for those who break things”."] },
    } },

    "e4-peces": { who: {}, nodes: {
      a: { say: ["In a cove of the lake, the water is warm and still. The water creatures that used to leap here are lying on the shore, in the cool mud, breathing fast.",
                 "A big creature with blue scales has a grey patch on its fin. It doesn't move it. Your creature approaches, sniffs it, and stays beside it without moving.",
                 "Further out, on the water, the surface bubbles slowly. There's a furnace underneath."],
           opts: ["Take the creatures to the north shore, where the water is cold", "Pour cold water into the cove", "Stay with the creature with the grey patch"] },
      norte: { say: ["You take the creatures one by one to the north shore, carrying them, dragging them, coaxing them. It takes all day.",
                     "In the cold water, some dive and come back up, shaking themselves. The one with the grey patch doesn't dive. It stays floating, still, looking at you."] },
      fria: { say: ["You haul buckets of river water and empty them into the cove. It's like filling a lake with a teacup. By dusk your arms are wrecked.",
                    "The cove water is a little less warm. A small creature slips in and swims in circles. It isn't enough for the others. But that one swims."] },
      quedarte: { say: ["You sit in the mud beside the big creature. Your creature lies against it. The night passes.",
                        "At dawn the creature with the grey patch moves its fin. Slowly. Once. Then it drags itself into the water and sinks.",
                        "You don't know if it went to die or to live. Your creature stares at the water for a long time."] },
    } },

    "e4-rada": { who: { rada: "Rada, of the Tides" }, nodes: {
      a: { say: ["When the water drops on the south shore, a woman of the Tides walks among the stones of the sunken square with her eyes closed and her hand on the walls.",
                 "My name is Rada. My grandmother taught me to read walls with my fingers. She was Orilla. We Tides have a habit of reading what the water covers.",
                 "Now that the water boils and drops, walls appear that we've never seen. There's one that talks about the sunken forge. And about the one who worked there."],
           opts: ["“Your grandmother walked here with her hand on the walls.”", "“Your grandmother counted the lights going out.”", "“The Tides were the keepers of the lake.”", "“What does the forge wall say?”"] },
      camina: { say: ["Every day the water dropped. I followed her. That's how I learned. She said walls don't lie because nobody wrote them for anyone to read.",
                      "What's written for nobody is the truest thing there is."] },
      luces: { say: ["She counted them. Then she counted the ones who walked past without looking at her. I always looked at her. That's why she taught me.",
                     "She told me: when there are no lights left to count, read the stones. Stones stay."] },
      guardianas: { say: ["We were. We charged little and took less. Now the Guild takes from below and the Houses charge from above. All that's left for the keepers is to watch.",
                          "But watching is keeping too. At least someone sees what happens."] },
      pared: { say: ["Rada puts your hand on the stone, next to hers. You feel grooves, short, in rows.",
                     "It says: “I worked in the water so the metal would cool. The water wasn't enough. The metal doesn't cool. It only moves: from the vein to the hand, from the hand to the stone”.",
                     "And below, smaller: “To whoever comes: the metal belongs to the Root. What you take from it, it charges to your body”."],
               opts: ["“This has to go to the Heart.”", "“Copy it on paper for the Guild.”", "“Leave it here. The water will cover it again.”"] },
      corazon: { say: ["A wall? You can't carry a wall.",
                       "You think about it. You tell her she can be carried: the fingers that read it.",
                       "Then I'll go. With my eyes closed, like my grandmother. Let the Tides carry what the lake kept."] },
      copiar: { say: ["Rada copies the wall onto paper, letter by letter, eyes closed and her left hand on the stone. It takes all afternoon.",
                      "Fogarín receives the paper. He reads it twice. He puts it in his apron.",
                      "He didn't tear it up. He didn't show it. He kept it. Sometimes that's the worst thing anyone can do with something true."] },
      dejar: { say: ["Yes. Let it cover it. What's written for nobody isn't for us.",
                     "That night the water rises. But not as much as before: the lake has less water every year. The wall stays half covered."] },
    } },

    "e4-vapor": { who: { fuelle: "Fuelle, young master", salitre: "Salitre, fisher" }, nodes: {
      a: { say: ["On the south shore, Fuelle and three workers are driving copper pipes into the boiling water. The pipes climb the slope, towards the Meadow.",
                 "Caretaker! Look at this. The lake steam goes up the pipes to the Meadow houses. Free heat all winter. The lake boils anyway, so at least let it be useful!",
                 "Free heat for the Houses. And for the Quarter? And for us, who live beside the boiling water?"],
           opts: ["“Free for whom, Fuelle?”", "“Let the pipes go to the Quarter first.”", "“Let the Tides run the valves.”", "“Take the pipes out. This is like the long tubes.”"] },
      quien: { say: ["Well, not free. The Guild lays the pipes. The Houses pay for the pipes. The Houses get the heat.",
                     "What do you want? That's how it works. Whoever lays it, charges. The Guild was bought all its life. Now it sells."] },
      barrio: { say: ["The Quarter? The Quarter doesn't pay for pipes.",
                      "You remind him of the vote with the black stones. That the workers are from the Quarter. That the heat he sells comes out of their hands.",
                      "All right. One pipe in three to the Quarter. And don't look at me like that, it's more than anyone ever gave them."] },
      valvulas: { say: ["Us? The Tides deciding how much steam goes up?",
                        "The Tides know nothing about pipes.",
                        "We know about water. A thousand years knowing about water. If the lake drops too much, we close. If it rises, we open. That we do know.",
                        "Fuelle thinks about it. He gives her the key to the first valve. Salitre hangs it round her neck on a cord of net."] },
      sacar: { say: ["You pull the first pipe out of the water. A jet of steam burns your forearm. Fuelle shouts.",
                     "Do you know what a pipe costs?",
                     "The workers don't drive in the second. They wait. Fuelle watches the lake boil with nobody making use of it.",
                     "Fine. Let it boil for nothing, then. As always."] },
    } },

    "e4-cuaderno": { who: { salitre: "Salitre, fisher" }, nodes: {
      a: { say: ["Salitre has a notebook of damp pages, tied with net thread. She opens it on a stone. Numbers. Fish, coins, weeks.",
                 "My grandmother had one just like it. She was Ola, you know? The Tides' Ola. She wrote everything down too.",
                 "I count what they pay us. The number goes up. And the lake goes down. Look: every time the number goes up, the water drops a finger. It's the same sum."],
           opts: ["“Your grandmother never reached zero.”", "“Your grandmother signed with the Houses.”", "“Stop charging. Let there be no sum.”", "“Take the notebook to the Guild and show them the sum.”"] },
      cero: { say: ["Never. She died with a small number on the last page. Seven barrels. I don't know what they were for.",
                    "I don't want to die with a big number. I'd rather the small one. At least the small one looks like something you look after."] },
      firmo: { say: ["She signed. We have papers for the north shore. The Tides don't wander. We don't remember why we wandered either.",
                     "Now I do remember. We wandered because water moves. If you stay still beside the water, you end up charging it."] },
      dejar: { say: ["Stop charging? And let them boil the lake for free?",
                     "She closes the notebook. She presses it to her chest.",
                     "You're right and you're not. If I don't charge, the Guild digs anyway. If I charge, the Guild digs and I have coins. The lake drops either way. I'll keep the coins. And the shame, which also keeps."] },
      mostrar: { say: ["You go with Salitre to the Crater. She opens the notebook in front of the twelve masters, at the long table.",
                       "Here. Every coin they pay us, a finger less of water. You're not buying cooked fish. You're buying the lake. A finger at a time.",
                       "The masters look at each other. Fogarín asks for the notebook. He reads it all, in silence, while everyone waits.",
                       "That week the Guild closes two furnaces under the lake. Not ten. Two. The water stops dropping in the north cove."] },
    } },

    "e4-cala": { who: { salitre: "Salitre, fisher", galena: "Galena, miner" }, nodes: {
      a: { say: ["One morning, the south cove wakes up dry. All the water drained in one night, through a crack in the bottom. Where the lake was there's baked mud and white fish stuck to the ground.",
                 "In the middle of the dry cove a red vein shows, wide as a road, running down towards the Heart. It beats. You can see it beat with the naked eye.",
                 "It's the biggest I've ever seen. With this the Guild makes ten bells.",
                 "With this the whole lake drains. The crack is the vein. The water goes where the metal comes up."],
           opts: ["Plug the crack with stones and mud so the water comes back", "Let the Guild take the vein", "Sing the lullaby to the vein"] },
      tapar: { say: ["You call the Tides, the miners, the Tuesday workers. A hundred come. They haul stones and mud for three days.",
                     "The crack is plugged. Rainwater starts to gather in the cove, slowly. It will take years to fill.",
                     "Years. Fine. The lake took a thousand to form. It can take a few to come back.",
                     "And the vein stays below, beating. Now we know where it is. So does the Guild."] },
      sacar: { say: ["You do nothing. The next day the Guild miners arrive with picks and barrows. They take out the vein in a week.",
                     "With that metal the great Bell is finished. Fuelle is happy.",
                     "The cove won't come back. The water keeps draining through the vein's hole. Slowly. A little every day."] },
      nana: { say: ["You sit in the baked mud and sing. Salitre doesn't know the words, but she hums. Galena taps the rhythm with her pick, on the stone, in twos.",
                    "The vein's beat slows. The red darkens. The crack doesn't close, but it stops swallowing.",
                    "It calms with the lullaby. It always calms with the lullaby. So why are we making a bell?",
                    "Nobody answers. Salitre writes something in the notebook: not a number, a word."] },
    } },
  });

  /* ---------- Echo Caves: Cuarzo, the foreman, the collapse, the Night of the Echo and what knocks from the other side ---------- */
  add("caves", {
    "e4-cuarzo": { who: { galena: "Galena, miner" }, nodes: {
      a: { say: ["In the Echo Hall, Galena shows you the walls carved by Cuarzo, the Hondura's chronicler, sixty years ago. There are whole nights carved there, names, half a lullaby.",
                 "Cuarzo was my grandfather's grandfather. Or something like that: in the Hondura we count oddly. He carved until his chisel wore out.",
                 "The miners pass by here every day and don't look. The walls are so full they look like smooth stone now."],
           opts: ["“He stopped carving and people told the nights out loud.”", "“He erased his grandfather's names to carve Vigils.”", "“He found older carvings, far below.”", "“Read a wall out loud.”"] },
      voz: { say: ["Yes. For years, in the Hall, people told the nights out loud. Then the Guild brought in double shifts and nobody had time to come.",
                   "The Hall has been empty at night for ten years. Walls say nothing if nobody comes."] },
      borro: { say: ["He used to shout them on the Night of the Echo. When he died, nobody learned them. Those names aren't anywhere.",
                     "In the Hondura we say what nobody says, the stone keeps. I suppose those names are stone now."] },
      viejos: { say: ["Yes. I found them too, in the hot tunnels. They're hands. Hands carved with a line beside them. Like the ones at the lake forge.",
                      "Cuarzo didn't say what they said because he couldn't read them. I can't either. But I can count: there are forty-two."] },
      leer: { say: ["Galena reads a wall out loud: a Vigil from sixty years ago, with names, with what each people sang. Her voice bounces around the Hall.",
                    "Two miners passing by stop. Then five. They sit on the floor. Galena reads until her mouth is dry.",
                    "Tomorrow I'll read another. If they come, I read. If not, I read anyway. Stone doesn't complain."] },
    } },

    "e4-capataz": { who: { plomo: "Plomo, Guild foreman", galena: "Galena, miner" }, nodes: {
      a: { say: ["At the mouth of the hot tunnels, a Guild foreman with a slate counts barrows. He has clean nails and a tired voice.",
                 "Double shifts until the Bell is finished. Orders from above. Whoever doesn't want to, can leave. There's a queue on the south slope to get in.",
                 "Double shifts in the hot tunnels mean grey hands in three moons, Plomo. You know that.",
                 "I know how to count barrows. They don't pay me for the rest."],
           opts: ["“And if they all refuse at once?”", "“Put the double shifts in the cold tunnels.”", "“Put cold water at the tunnel mouth. Let them wash their hands.”", "Start pushing barrows yourself so the miners can rest"] },
      todos: { say: ["Then the Guild brings in the slope folk, who don't know. And the Hondura folk are left without work and without hands anyway, because theirs are already half grey.",
                     "Don't think I like it. My father was a miner. I'm a foreman so I don't have to be a miner. That's the only thing I ever did right."] },
      frios: { say: ["In the cold ones? There's no metal there.",
                     "You explain: double shifts in the cold tunnels, cutting stone for the moulds; single shifts in the hot ones. Same hours. Fewer grey hands.",
                     "There'll be fewer barrows of metal. Up top they'll be angry.",
                     "He looks at Galena. He crosses something out on the slate.",
                     "Let them be angry. I'm the one who counts the barrows."] },
      agua: { say: ["With Galena you bring two barrels of water from the cold seeps and set them at the tunnel mouth. Every miner who comes out dips their hands up to the elbow.",
                    "My grandfather said cold water doesn't cure, but it slows. Slowing is fine. Slowing is all you can do."] },
      empujar: { say: ["You push barrows all afternoon. Ten miners rest sitting against the wall, hands in their laps.",
                       "By the end your palms are red and hot. You wash them in cold water, as Galena said, until they stop burning.",
                       "Ten rested one afternoon. Tomorrow they're back. You can't push every afternoon."] },
    } },

    "e4-derrumbe": { who: { galena: "Galena, miner", plomo: "Plomo, Guild foreman" }, nodes: {
      a: { say: ["A dull, long rumble runs through the Caves. Dust falls from the ceiling. Then, silence. Then, shouting: hot tunnel number seven has collapsed.",
                 "Six inside. Six. I had six written down.",
                 "Galena presses her ear to the fallen rocks. She knocks twice with her pick. She waits. From the other side, faint, two knocks answer. Then two more. Then one."],
           opts: ["Dig with your hands, now", "Ask the Guild for tools and people", "Send your creature through a small crack"] },
      cavar: { say: ["You dig with Galena and twenty miners, by hand, passing stones from hand to hand. The stones in this tunnel are hot. They burn your fingers.",
                     "It takes a day and a night. They get five out. The sixth hasn't answered the knocks since morning.",
                     "Five. The Hondura gets its own out with its hands. Always. Even if they turn grey.",
                     "You look at your hands. There's red dust under your nails that won't wash out."] },
      gremio: { say: ["I'll go. I'll run.",
                      "Plomo comes back in an hour with Fogarín, ten Crater workers and crowbars of root metal. The crowbars open the stone like mud.",
                      "They get all six out alive. The Crater workers' hands are greyer after using the crowbars.",
                      "The metal that sickens us got us out. I don't know what to think about that. I don't know if I should say thank you."] },
      criatura: { say: ["Your creature looks at the crack. It looks at you. It goes in. It's a while before you stop hearing its steps.",
                        "After a time, from the other side, someone cries out in surprise. Then, voices. Your creature comes back with a rag tied round its neck: a map drawn in soot of where they are.",
                        "With the map, the miners dig exactly where they need to. They get all six out before dawn.",
                        "Your creature knows how to go where we can't. Down here, that's worth more than a pick."] },
    } },

    "e4-ecos": { who: { galena: "Galena, miner" }, nodes: {
      a: { say: ["It's the Night of the Echo. The whole Hondura gathers in the Hall, with lamps. On this night, once, they shouted the names of the dead so the stone would repeat them.",
                 "This year, half the people don't shout names. They shout numbers: barrows, coins, shifts. They laugh. The stone repeats the numbers just the same.",
                 "It's the first time the Hondura has earned well. People are happy. I don't know if it's wrong that they're happy."],
           opts: ["Shout the name of the miner who didn't come out of the collapse", "Shout the forty-two names from the list", "Shout “hands”", "Don't shout. Let them celebrate."] },
      nombre: { say: ["You shout the sixth one's name. The stone repeats it, once, twice, three times, further away each time.",
                      "The Hall goes quiet. Someone cries. Then a voice shouts another name, from another year. And another.",
                      "There it is. The Hondura remembered what this night is for. It took a new dead to remember the old ones."] },
      lista: { say: ["You read out the names on the new wall, one by one, all forty-two. The stone repeats them. The miners fall silent.",
                     "When you finish, Galena knocks on the wall twice. From far below, distant, two knocks answer.",
                     "They heard us. I don't know who. But they heard us."] },
      manos: { say: ["You shout “hands”. The stone repeats it: hands, hands, hands, until it sounds like a hammer.",
                     "Some miners look at their own. One hides his in his pockets. Another raises hers, grey, for everyone to see.",
                     "One word. Sometimes one word is enough to make someone look at their hands."] },
      festejar: { say: ["You don't shout. The Hondura celebrates. The numbers bounce around the Hall until late.",
                        "At the end, when almost no one is left, Galena shouts a single name, softly. Her grandfather's. The stone repeats it once and goes quiet."] },
    } },

    "e4-pizca": { who: { pizca: "Pizca", plomo: "Plomo, Guild foreman" }, nodes: {
      a: { say: ["In a tunnel so narrow no adult fits, a girl from the south slope crawls out pushing a bucket of red stones. Her knees are scraped and she has a lamp tied to her forehead.",
                 "My name's Pizca. I'm one of the small-tunnel kids. The Guild pays half, but we get in where the big ones can't.",
                 "My friend Chispa forges. I dig out what she forges. We're a team. Even if she doesn't know it yet."],
           opts: ["“How many kids work here?”", "Talk to Plomo about getting the kids out of the tunnels", "Take Pizca to Chispa", "Teach her to count knocks, like the Hondura"] },
      cuantos: { say: ["Thirty. Thirty-one with the new one. The youngest are seven. I'm ten, I'm one of the old ones.",
                       "Don't worry. They give us cold water and bread. And if our nails go grey, they move us to the outside tunnel. That's what they say."] },
      plomo: { say: ["Plomo listens with his slate against his chest.",
                     "If I take them out, the Guild puts in other kids, from another slope. Or it closes the small tunnels and loses the metal. Or it takes me out and puts in another foreman who doesn't ask.",
                     "But that night Plomo wipes the thirty-one names off his slate. The next day he nails a board across the small tunnels: “Closed due to collapse”. There was no collapse."] },
      chispa: { say: ["You take Pizca to the stone forge on the slope. Chispa eyes her with suspicion. Pizca shows her a red stone from the bucket.",
                      "I dig this out. You use it to make the iron hold.",
                      "Chispa looks at the stone. She looks at Pizca's scraped knees. She looks at her own grey nail.",
                      "The next day the two of them forge cold, nothing red. It takes three times as long. They laugh twice as much."] },
      golpes: { say: ["You teach her what Galena taught you: two knocks, someone's stuck below; one long one, all fine; three quick ones, everyone out.",
                      "I know a stone language now! I'm going to teach it to all the small-tunnel kids.",
                      "A week later, when a ceiling falls in a small tunnel, the kids warn each other with three quick knocks. They all get out. Nobody gets hurt."] },
    } },

    "e4-paredmanos": { who: { galena: "Galena, miner", escoria: "Escoria, worker", fogarin: "Fogarín, Master of the Guild" }, nodes: {
      a: { say: ["In a new gallery, far from the Hall, there's a wall full of carved hands. Under each one, a name. Some are from today's Guild. Others, from the list of a thousand years ago.",
                 "There are people in front of the wall. Crater workers with grey hands, Court charcoal burners with moss over their mouths, Hondura miners. They don't talk. They look.",
                 "They came on their own. Nobody called them. They walked down from the Crater to see their names in the stone.",
                 "The Hondura carves so nobody forgets. It never carved for the living. This is the first wall of the living."],
           opts: ["“Let every people carve their own here.”", "“Let the Guild Master see it.”", "Carve your own hand"] },
      todos: { say: ["For a moon people come down from everywhere. Woodcutters from the Forest, fishers from the Tides, carters from the Heights. Each carves a hand and a name.",
                     "The wall fills up. Galena opens another gallery next to it. It fills up too.",
                     "Nine peoples on one wall. If the Heart calls, the Hondura will go with this. Not with barrows. With hands."] },
      fogarin: { say: ["Fogarín comes down to the Caves for the first time in his life. He walks slowly, with a cane. He stands in front of the wall for a long while.",
                       "He searches for a name with his finger. He finds it: his grandfather's grandfather, from Ébano's list. Beside it, Yunque's hand, freshly carved.",
                       "A thousand years and we're still putting names on the same wall. This isn't a Guild. It's a cemetery that works.",
                       "He asks for a chisel. He carves his own hand. The one with the grey line on the nails."] },
      tumano: { say: ["You lay your hand on the stone. Galena outlines it with a nail and carves it slowly. Underneath you put the name they call you at the Ford.",
                      "Your creature rests its paw beside it. Galena carves that too, without asking.",
                      "The Caretaker has a clean hand. Fine. Let there be one clean hand on the wall, so we remember what they were like."] },
    } },

    "e4-otrolado": { who: { galena: "Galena, miner" }, nodes: {
      a: { say: ["Galena takes you to the deepest tunnel of all, where the wall knocks in twos. She brings a pick of root metal she borrowed from the Guild.",
                 "I'm going to open it. This wall has been answering me for a year. I want to see who.",
                 "She strikes. The stone opens in a hole the size of a door. Warm air comes out from the other side, still, old.",
                 "Inside there's a round chamber. Along the walls, sitting, standing, leaning, there are stone figures shaped like people. Many. They have tools in their hands. Some have their mouths open, as if singing."],
           opts: ["“Are they... the ones on the list?”", "Go in and touch a figure", "Seal the chamber again", "Bring everyone to see it"] },
      lista: { say: ["Forty. I count forty. The list said thirty-nine with grey hands. And one crossed out. Forty.",
                     "They didn't die. They stayed. They kept working until they turned to stone completely. And someone put them here. Or they came on their own.",
                     "In the middle of the chamber there's a red vein beating. The knocks in twos are the heartbeat, bouncing off forty bodies of stone."] },
      tocar: { say: ["You touch a figure's shoulder. It's warm. Under the stone, very slowly, something beats. It isn't the vein. It's slower.",
                     "The figure doesn't move. But your creature growls softly, ears back, and won't come closer.",
                     "They go on. They're alive in some way. The way stone is alive. Slowly. Very slowly."] },
      sellar: { say: ["Galena looks at you for a long while. Then she nods. They close the hole with stone and mortar.",
                      "Galena carves on the sealed wall: “Here are the forty. Do not dig”. And beside it, forty tiny hands.",
                      "We let them rest. If you can call it that. At least nobody will use them as barrows."] },
      mostrar: { say: ["For a week people come down from all over the Glade to see the chamber of the forty. Miners, workers, Guild masters, Houses folk with handkerchiefs over their noses.",
                       "Some come out crying. Others, silent. A young master comes out and throws up. Fuelle comes out last and says nothing the whole way back.",
                       "Now they know. What's going to happen to us already happened. Forty times. What I don't know is whether knowing changes anything."] },
    } },
  });

  /* ==================== Delivery 4: the Heights, the Deep and the Heart ==================== */

  /* ---------- The Heights: red snow, the lookout, the buyer from outside, the verses and the sword that comes back ---------- */
  add("heights", {
    "e4-nieveroja": { who: {}, nodes: {
      a: { say: ["On the pass road, the snow isn't white. It's pink, in patches, and in places red as a wound. The metal carts leave a fine dust that the wind spreads over the slopes.",
                 "The mountain creatures eat that snow. A white Heights goat licks a red patch and then stands still, legs rigid, staring at the valley.",
                 "Your creature sniffs the red snow and sneezes. It doesn't touch it. It looks at you as if asking why it's like this."],
           opts: ["Cover the patches with clean snow", "Carry the rigid goat to the village", "Gather red snow to show down below"] },
      tapar: { say: ["You throw clean snow over the patches with your hands, your feet, a board. It's like sweeping the sea. The whole road is stained.",
                     "At dusk another line of carts goes by. The red dust falls again. Your creature sits by the road and won't go on."] },
      cabra: { say: ["You carry the goat to the slope village. It weighs more than it should. Its legs are hard and cold, like stone.",
                     "An old woman rubs it with grease by the fire all night. At dawn, the goat bends one leg. Then the other.",
                     "The old woman says nothing. She puts a sign on the pen door: “Don't eat the red snow”. She draws it, for those who can't read."] },
      juntar: { say: ["You fill a leather bag with red snow. On the way down the snow melts and leaves a red mud at the bottom of the bag, warm.",
                      "At the Ford you put it in a jar on the shelf, with a label: “The Heights”. People who pass look at it and ask. You tell them."] },
    } },

    "e4-mirador": { who: { toldo: "Toldo, of the Heights" }, nodes: {
      a: { say: ["At the wind lookout there's a striped awning, worn, patched many times. Underneath, a middle-aged man sells hand-drawn maps of the passes.",
                 "My name's Toldo. My grandfather was Trueque, the one with the awning. He sold slices of nights. I sell slices of mountain: where to take a hot cart without bringing the snow down.",
                 "Everybody sells something at this lookout. My grandfather used to say the wind buys everything and never pays."],
           opts: ["“Your grandfather showed the whole night, for free.”", "“Your grandfather got rich selling slices.”", "“Your grandfather said he sold the same as always.”", "“Do your maps show where the snow falls?”", "“Give the maps to the carters.”"] },
      entera: { say: ["Yes. And he sold little jars beside it, dearer than ever. One thing paid for the other.",
                      "I do the same. I give the safe-pass map to the slope villages. And I sell it dear to the Guild. The Guild pays for everyone."] },
      rico: { say: ["Rich. With a house in the Meadow and a nasty dog. When he died, the Houses took the house for his debts. The dog came with me.",
                    "There he is, look, under the table. He doesn't bite anymore. What you earn selling slices, you lose all at once, whole."] },
      mismo: { say: ["“The same as always.” Yes. Nobody knew what to answer. I still don't.",
                     "I think he sold what people wanted to believe. Which is always the same, even if the jar changes."] },
      mapas: { say: ["They show where it fell. Where it's going to fall, nobody knows. Since the carts started coming through, the mountain changes faster than my drawings.",
                     "He shows you a map. There are red crosses on three slope villages.",
                     "I drew these crosses this year. Last year there weren't any."] },
      regalar: { say: ["Give them away? To the carters, who haul the metal?",
                       "You tell him the carters are the first to die when the snow falls. That the metal will go through anyway, map or no map.",
                       "My grandfather would kill me. Well, he's already dead. I'll give them away. But the ones for the Guild, I charge triple."] },
    } },

    "e4-afuera": { who: { cizalla: "Cizalla, buyer from outside", peaje: "Peaje, carter" }, nodes: {
      a: { say: ["At the highest inn on the pass there's a woman who isn't from the Glade. She wears thick wool clothes in a colour that isn't dyed here, and she speaks with a clipped accent. There's a sword on the table.",
                 "My name is Cizalla. I buy metal for the lords on the other side. They make wars. I make purchases. Each has their trade.",
                 "This sword is made of your red metal. It doesn't chip. It doesn't cool. My lords want a thousand. They pay in gold. You don't know what gold is worth outside.",
                 "I brought her this far. She wants to see the Crater. She wants to talk to the Guild directly, without the Heights in the middle."],
           opts: ["“Against whom are those wars?”", "“Swords that never cool turn hands to stone too.”", "Take her to the Crater", "“Go back the way you came.”"] },
      guerras: { say: ["Against other lords. There are always other lords. Don't worry: the Glade is far away and small. Nobody makes war on a valley with no gold.",
                       "For now. The red metal could change that. I tell you because I'm honest, not because I care."] },
      manos: { say: ["Hands?",
                     "You tell her. She listens without interrupting. At the end she looks at the sword. She looks at the hand she carried it with on the road.",
                     "My lords don't touch the swords. The soldiers touch them. Soldiers don't ask questions. Thank you for telling me. It won't change anything. But now I know."] },
      llevar: { say: ["You take Cizalla to the Crater. Fogarín receives her in the masters' hall. Fuelle can't take his eyes off the bag of gold.",
                      "They talk all afternoon. In the end, the Guild signs: two hundred ingots a year for outside, in exchange for gold. The Heights keep the hauling, but not the deal.",
                      "That's it. Now the Glade sells wars to others. And I carry them in my cart."] },
      volver: { say: ["Go back? I've crossed three mountains.",
                      "And you'll cross three back. I'll take you. Free.",
                      "Cizalla laughs. She puts the sword away. She leaves at dawn, with Peaje and two oxen, without the deal.",
                      "Another will come. Another always comes. But not this year."] },
    } },

    "e4-versos": { who: { romanza: "Romanza, messenger" }, nodes: {
      a: { say: ["In a cave on the summit, where the Heights messengers used to rehearse the verses they carried from village to village, there's only one woman, young, with a small drum.",
                 "I'm Romanza. I'm the last messenger of the Heights. The rest became carters. Carrying metal pays. Carrying verses doesn't.",
                 "I know a hundred and forty verses by heart. The whole lullaby, too. Nobody has asked me for one in two years."],
           opts: ["“Sing me one.”", "“Take the lullaby to the Crater furnaces.”", "“Teach the verses to the carters, for the road.”", "“Write the verses down before they're lost.”"] },
      cantar: { say: ["Romanza beats the drum slowly and sings an old Heights verse: a message from one village to another warning that the snow was going to fall, three hundred years ago.",
                      "That verse saved a village. Now the warning comes from one of Toldo's maps. It's more accurate. But nobody sings it."] },
      hornos: { say: ["Romanza goes down to the Crater with her drum. She stands at the mouth of the deep furnaces and sings the lullaby. The workers coming out stop.",
                      "The next day she comes back. The day after, too. The workers start waiting for her. Some sing it on the way down.",
                      "I don't know if it does any good. But they go down singing. Before, they went down silent."] },
      arrieros: { say: ["Romanza walks with the line of carts for two weeks. She teaches them the pass verses: where the snow falls, where there's water, where not to stop.",
                        "They learned them. They sing them to stay awake. They carry metal and verses in the same cart. It's odd. But the Heights always carried two things at once."] },
      escribir: { say: ["Romanza dictates. You write. It takes three days: a hundred and forty verses and the lullaby, whole, with the notes drawn as best she can.",
                        "Now they're on paper. If I die, they stay. But a written verse doesn't travel by itself. Someone has to sing it."] },
    } },

    "e4-trineo": { who: { peaje: "Peaje, carter" }, nodes: {
      a: { say: ["On a bend of the pass, a cart has gone off the road. It's tipped over in the snow, half melted. The hot ingots have opened smoking holes all around. An ox is trapped underneath.",
                 "It was my cousin's! He jumped. The ox didn't.",
                 "The ox bellows. Under the cart, the snow sinks slowly, melted by the ingots."],
           opts: ["Lift the cart all together", "Get the ingots out first, so it stops sinking", "Cut the harness and pull the ox out"] },
      levantar: { say: ["You call the carters. Ten people, with poles, lift the cart a hand's breadth. The ox crawls out, with a broken leg.",
                        "The cart falls again. It sinks into the hole of melted snow and disappears. The ingots too.",
                        "The load's lost. The Guild will charge my cousin for it. But the ox lives. My cousin will look after it even if he has to eat less."] },
      lingotes: { say: ["You grab the ingots with wet hides and throw them into the snow, far off. Each one opens a smoking pit where it lands. You burn your fingers through the leather.",
                        "The cart stops sinking. But the ox doesn't bellow anymore. It's gone still underneath, eyes open.",
                        "We saved the metal. The metal always gets saved. It's the only thing that doesn't die."] },
      arneses: { say: ["You cut the harness with Peaje's knife. Three of you pull the ox. It comes out bellowing and stands in the snow, trembling.",
                       "The cart sinks by itself. The ingots are lost at the bottom of the hole, where they keep smoking.",
                       "Down there they'll stay hot a hundred years. When the snow melts in spring, this stream will run warm down to the Lake. We'll see what it does."] },
    } },

    "e4-espada": { who: { peaje: "Peaje, carter", cizalla: "Cizalla, buyer from outside" }, nodes: {
      a: { say: ["Down the north pass comes no cart but a person. It's Cizalla, the buyer from outside. She comes on foot, without oxen, her right arm wrapped in rags.",
                 "I've come to return this. Nobody asked me to. I'm asking myself.",
                 "She lays a red sword on the inn table. Beside it, she unwraps her arm. The hand is grey up to the elbow. She doesn't move it.",
                 "My lords won their war. The soldiers who held the swords have hands like mine. They can't hold anything anymore. Not even their pay."],
           opts: ["“Why did you come back?”", "“Take it to the Heart. Let them see it.”", "“Throw it in the Lake, where nobody will touch it.”", "“Stay. In the Glade we know about hands.”"] },
      porque: { say: ["Because you told me and I didn't care. Now I care. It comes late, it always comes late.",
                      "What leaves the Glade doesn't come back, the old folk said. It comes back. It comes back on someone else's arm."] },
      corazon: { say: ["Cizalla and Peaje take the sword to the Heart. They drive it into the ground at the foot of the third statue, beside the slag.",
                       "Let the nine see it. Let them see what what you make in here does out there.",
                       "The Heights will go to the Heart with this. Not with carts. With what the carts bring back."] },
      lago: { say: ["You throw the sword into the Lake from the north shore. It falls point first and sinks without a splash. Where it fell, the water starts to steam.",
                    "It sank. But the lake will boil a little more there. None of this goes away entirely. It just moves."] },
      quedarse: { say: ["Stay? In a valley with no gold?",
                        "She looks at her grey hand. She looks at the inn, the fire, Peaje.",
                        "Fine. I have nowhere to go with one hand. I'll stay in the Heights. I'll teach what I know of outside. So they know what's on the other side of the mountains, in case it comes one day."] },
    } },

    "e4-cumbre": { who: { peaje: "Peaje, carter", romanza: "Romanza, messenger" }, nodes: {
      a: { say: ["In the square of the highest village in the Heights, the carters and the last messengers gather around a fire. The news has come: the peoples are meeting in the Heart over the Bell.",
                 "If we go, they'll ask us to stop hauling the metal. And the Heights live off that.",
                 "If we don't go, the Heart decides without anyone who knows what's on the other side of the passes."],
           opts: ["“Let the carters go, with what they hauled.”", "“Let Romanza go, with the verses.”", "“Don't go. Let the ones below decide.”"] },
      arrieros: { say: ["With what we hauled. With the carts, the burns, the dead oxen. With the accounts too. Let them know how much they pay outside.",
                        "The carters raise their hands, one by one. Their palms are burnt from gripping hot tarps.",
                        "We go. And if they ask us to stop hauling, we'll ask for something in return. The Heights give nothing away. But they listen."] },
      romanza: { say: ["Me? Alone, with a drum?",
                       "With all of us behind you. But you speak. Let the Heights carry a message and not an ingot, for once.",
                       "Romanza beats the drum. The carters sing the verse of the falling snow. It's the first time in years it's been heard on the summit."] },
      novan: { say: ["Let them decide. And tell us afterwards what to haul. As always.",
                     "The fire goes out early. Romanza goes back to her cave without beating the drum."] },
    } },
  });

  /* ---------- The White Deep: the leaks, the Watch, Nieve, ice for sale and what the ice kept ---------- */
  add("deep", {
    "e4-goteras": { who: { copo: "Copo" }, nodes: {
      a: { say: ["In an ice hall of the Deep, twenty kids sitting on the floor set cups, bowls and boots under the leaks. When one fills, they empty it into a barrel and put it back.",
                 "My name's Copo. This is the school. Well, it was. Now it's the leak hall. The teacher says counting drops is learning too.",
                 "Today we counted three thousand. Yesterday, two thousand eight hundred. Tomorrow there'll be more. That we did learn."],
           opts: ["“Why don't you move up top?”", "Help plug the leaks with packed snow", "Teach them a game with the drops"] },
      arriba: { say: ["Up top is full already. Old folk first. Then the ones with creatures. Then us.",
                      "It doesn't matter. Down here at least you can hear the music of the drops. Up there it's too quiet."] },
      tapar: { say: ["You pack snow with your hands and push it into the cracks in the ceiling. The kids climb on each other's shoulders. It takes all afternoon.",
                     "The leaks stop. For one night. The next morning, the packed snow drips just like the ice.",
                     "Well. At least we slept dry one night. Tomorrow we plug them again. It's like a job."] },
      juego: { say: ["You teach Copo to listen to the drops: each one falls in a different cup and sounds different. If you put them in order, they sound like a song.",
                     "In an hour the kids have lined up forty cups. The lullaby plays, in drops, off-key, slow.",
                     "The ceiling sings! The teacher will say it isn't learning. But it sounds nice."] },
    } },

    "e4-turno": { who: { carambano: "Carámbano, of the Watch" }, nodes: {
      a: { say: ["The circle of the Watch is still in its ice hall, but the ice drips on the sleepers. There are fewer dreamers than before. Each has a waxed blanket over them.",
                 "I'm Carámbano. I've kept the Watch since Nevisca died. We still sleep. I'm not sure for whom. Not even the Meadow families pay anymore: they buy Bell turns.",
                 "The odd thing is that everyone who sleeps here has dreamed the same thing for a year: a sound you can't hear and something enormous going still."],
           opts: ["“Nevisca slept for the Root with half the dreamers.”", "“The Deep charged double for every dream.”", "“Nevisca took in those who arrived with hollows.”", "“That dream is the Bell.”", "“Wake them up. Nobody should be made to dream that.”"] },
      raiz: { say: ["Yes. Half still do. We dream white, as she used to say. But now the white has a red line down the middle. It won't go away.",
                    "If we dream what the Root dreams, the Root is afraid. I'd never dreamed it afraid before."] },
      doble: { say: ["Double. And then nobody paid anything. We have firewood for ten winters and nobody to buy it.",
                     "Now we give the dreams away. Nobody wants them. A free dream is worth less than a dear one, even if it's the same."] },
      huecos: { say: ["We still do. They come from the Crater now. With grey hands and a hollow. They're not missing a memory: they're missing touch. They can't tell if something is hot.",
                      "We give them broth. They hold it with both hands and don't know if it burns. We drink it with them, to warn them."] },
      campana: { say: ["The Bell? We're dreaming the Bell before it rings?",
                       "He looks at the sleepers. One stirs, moans, goes still again.",
                       "Then the Watch knows what's going to happen. And nobody asks the Watch. I'll write the dreams down. All of them. In case anyone wants to know what the Root feels."] },
      despertar: { say: ["Carámbano wakes the dreamers one by one. Some cry when they open their eyes. One asks whether it has rung yet.",
                         "No. Not yet. Go home. If the Root wants to dream in fear, let it dream alone for a while. We are not its fear.",
                         "The Watch is empty for the first time in a thousand years. It drips on the waxed blankets, empty."] },
    } },

    "e4-nieve": { who: { nieve: "Old Nieve" }, nodes: {
      a: { say: ["On the Deep's frozen lake, which now has puddles of water on top, an old woman skates slowly, a cane in each hand. One lap, two. She stops beside you, out of breath.",
                 "Caretaker. It's Nieve. The ice girl. I still skate, look. Badly. But I skate.",
                 "This winter the lake didn't freeze all the way. There's water underneath, moving. When I skate, I hear it. It sounds like when my brother fell."],
           opts: ["“You gave your brother back to the lake.”", "“You drank your brother's fall.”", "“You greet the cup every morning.”", "“Don't skate here anymore. It's going to break.”", "Skate a lap with her"] },
      devolvio: { say: ["I gave him back. The hole closed. Now the lake opens again, in other places. Maybe it'll give him back to me.",
                        "I don't want it to. Let him stay where he is. I've said goodbye."] },
      bebio: { say: ["I have his laugh. Still. Sixty years with someone else's laugh inside.",
                     "When the lake makes that sound, the laugh comes out by itself. The kids think I'm mad. Maybe I am."] },
      copa: { say: ["Every morning. The wax is intact. But this winter the cup sweats. On the outside. As if it were warm inside.",
                    "I won't open it. But I look at it more."] },
      noPatinar: { say: ["You're right. Everyone has told me. You're the first one to tell me while I'm standing on the ice.",
                         "She leaves the lake slowly, on her canes. She sits on the shore and takes off her skates.",
                         "Well. I've skated sixty years. Let the kids skate when it freezes again. If it does."] },
      patinar: { say: ["You skate with her, slowly, arm in arm. The ice creaks. The water moves underneath.",
                       "Halfway round, Nieve laughs. It's a child's laugh, very old and very new at once.",
                       "Thank you. Now, yes. If it breaks tomorrow, let it break. Today it held."] },
    } },

    "e4-hielero": { who: { tempano: "Témpano, ice keeper", fuelle: "Fuelle, young master" }, nodes: {
      a: { say: ["At the entrance to the Deep there's a line of empty Guild carts. The Deep folk cut blocks of old ice, blue, and load them. Fuelle counts the blocks.",
                 "The Deep's ice cools the Bell moulds better than anything. We pay them well. At last the Deep sells something!",
                 "We sell the ice that's melting because of your furnaces to cool what your furnaces heat. If you explain it slowly, maybe I'll find some sense in it."],
           opts: ["“How much ice is left?”", "“Let them pay in closed furnaces, not coins.”", "“Let them cut only the ice that's already melting.”", "Tip a cart of ice over on the road"] },
      cuanto: { say: ["At the current rate, ten years. With the carts, five.",
                      "In five years the Bell is ready and no more furnaces are needed. It's a good sum.",
                      "It's a good sum for you. For the Deep it's a countdown."] },
      hornos: { say: ["Closed furnaces? In exchange for ice?",
                      "Témpano folds her arms. The Deep folk stop cutting.",
                      "Fine. One furnace closed for every hundred blocks. Fogarín will kill me. Or congratulate me. With him you never know."] },
      derretido: { say: ["Témpano marks the blocks that are already dripping with red paint. Only those get loaded. They're fewer, smaller, softer.",
                         "This doesn't cool half as much.",
                         "Then your moulds take twice as long. And the Deep lasts twice as long. Seems fair to me."] },
      volcar: { say: ["You push a full cart until it tips over. The ice blocks shatter on the road, blue, glittering.",
                      "What are you doing? That was paid for!",
                      "Not anymore. It belongs to the Deep again. Even in pieces.",
                      "Fuelle leaves furious. The other carts leave empty. The next day they come back, with a guard."] },
    } },

    "e4-glaciar": { who: {}, nodes: {
      a: { say: ["At the edge of the Deep's glacier there's a long creak, like a tree breaking very slowly. A blue crack opens across the ice, from side to side.",
                 "On the other side of the crack some frost creatures are trapped: five, small, white, hiding among the blocks. The crack is widening.",
                 "Your creature runs to the edge, barks, runs back to you, runs to the edge again."],
           opts: ["Lay a plank across the crack", "Send your creature to guide them", "Go round the glacier from above"] },
      tabla: { say: ["You find a long plank and lay it across the crack. It creaks. You cross on all fours. You grab the creatures two at a time and pass them over.",
                     "When you go back for the last one, the plank snaps. You jump. You reach the other side with your legs dangling and haul yourself up on your elbows.",
                     "The last creature stays on the other side. It looks at you. It turns and goes deeper into the glacier, where it's still cold."] },
      criatura: { say: ["Your creature leaps the crack where it's narrowest. On the other side it gathers the five and leads them along the edge to an ice bridge you hadn't seen.",
                        "They cross in single file, behind it. All five. Your creature comes back last, its fur full of frost, proud."] },
      rodear: { say: ["You climb along the edge of the glacier for hours. By the time you reach the other side, the crack is a canyon. The creatures are gone.",
                      "You find them higher up, together, huddled in an ice cave that doesn't drip yet. They look at you. They don't come down.",
                      "You leave food at the entrance. As you go down, the glacier sounds again, far off."] },
    } },

    "e4-guardado": { who: { tempano: "Témpano, ice keeper", fogarin: "Fogarín, Master of the Guild" }, nodes: {
      a: { say: ["The Deep's oldest ice has melted down to the floor. Témpano takes you to see what was underneath. It's an enormous stone hall, its ceiling dripping.",
                 "On the floor, set out in rows, there are bells. Hundreds. Small, large, of stone, of bone, of dark metal. Every one has its tongue tied with cords that fall apart at a touch.",
                 "I didn't know. Nobody knew. The ice covered them. Someone, before every era we know of, made bells to put the Root to sleep. And then tied them. And then buried them in the cold."],
           opts: ["“Why did they tie them?”", "Carry a tied bell to the Heart", "Cover them with ice and snow again", "Tell Fogarín"] },
      porque: { say: ["I don't know. But look: there's a stone tablet at the entrance. The letters are old. Rada could read them with her fingers. I only understand one word, which repeats.",
                      "The word is “no”. Written many times. On every bell. As if each one who made one had written the same thing again."] },
      llevar: { say: ["You carry a small bell, made of bone, its tongue tied. It's light. Témpano walks with you to the Heart. She doesn't speak the whole way.",
                      "You leave it at the foot of the third statue, beside the Guild's test bell. The two of them, side by side. One tied. One not.",
                      "Let them see it. That someone before us had the same idea. And buried it. The Deep will go to the Heart with this."] },
      tapar: { say: ["You shovel snow over the bells with Témpano and ten Deep folk. It takes three days. On top you lay blocks of the ice that hasn't melted yet.",
                     "It won't hold. The heat keeps coming from below. But for now they're covered. Don't let the Guild find them. It would give them ideas."] },
      fogarin: { say: ["Fogarín comes down to the Deep wrapped in furs. He walks among the rows of tied bells. He touches one. He touches another. He sits on the wet floor.",
                       "It's been done. Many times. And they all tied them. And I thought I was the first.",
                       "He says nothing more. He goes back to the Crater that night. The next day, the great Bell is still in its mould. But the deep furnaces work at half."] },
    } },

    "e4-fondovoto": { who: { tempano: "Témpano, ice keeper", carambano: "Carámbano, of the Watch" }, nodes: {
      a: { say: ["In the upper hall, where the Deep moved, people gather around a brazier. For the first time in the Deep's history there's fire indoors. It's needed: the ones from below arrive soaked.",
                 "They're calling us to the Heart. Over the Bell. If we go, we'll ask for the furnaces to be put out. All of them. The Deep doesn't survive otherwise.",
                 "And if they're all put out, the Crater starves. They're people too. I sleep beside the ones who come with grey hands."],
           opts: ["“Go and ask for what you need. Let the Heart decide.”", "“Go and listen first.”", "“Don't go. Climb higher and wait.”"] },
      pedir: { say: ["Ask. Yes. It's what the Deep never did. We always waited for the cold to defend us.",
                     "She lifts a bucket of meltwater. She sets it in the middle of the circle.",
                     "We take this. Water that was everlasting ice. Let them see it, touch it. And then let them say whether the Deep asks too much."] },
      escuchar: { say: ["Listen. That we do know. A thousand years listening to the sleeping Root.",
                        "Fine. We'll go and listen. But if anyone says the Deep can wait, I'll speak. We've waited enough."] },
      esperar: { say: ["The Deep doesn't go. They climb higher, to the summit caves, and wait.",
                       "Let the news reach us. Good or bad. The cold always waited. Maybe it's the only thing we know how to do."] },
    } },
  });

  /* ---------- Heart of the Glade: the Stump, the statue, those who arrive, the name, the eve and the singers ---------- */
  add("heart", {
    "e4-tocon": { who: { retama: "Retama, keeper of the Stump" }, nodes: {
      a: { say: ["In the Heart, the Stump is warm. The roots showing above ground around it have red veins, fine, like veins under skin. The Stump's flowers open at night and close by day, the wrong way round.",
                 "I'm Retama. I keep the Stump. Brezo kept it before me. He said the Stump was cold as a river stone. Now it burns if you touch it too long.",
                 "The creatures don't come near like they used to. The ones that come, come to die. They lie down on the warm roots and don't get up."],
           opts: ["“Since when has it been warm?”", "Put your hand on the Stump", "Help her bury the creatures", "Sing the lullaby to the Stump"] },
      cuando: { say: ["Since the deep furnaces started. A little at first. Then more. Now, on Court nights, when it doesn't sleep, you can see a red glow in the cracks of the bark.",
                      "Brezo taught me to listen to the Stump. Now the Stump sounds different. Like someone with a fever."] },
      mano: { say: ["You put your hand on the Stump's bark. It's hot, like a sick child's forehead. Underneath, something beats fast.",
                    "You stay like that a while. The beat doesn't calm. But afterwards your hand stays warm for hours.",
                    "You felt it. Your face changed. Brezo used to make the same face."] },
      enterrar: { say: ["With Retama you dig three small graves at the foot of the Stump. The creatures are light. Their legs are grey.",
                        "Your creature watches from a distance. When you finish, it comes over and lies down on the turned earth.",
                        "The Glade's creatures were always buried here. They used to be old. These are young."] },
      nana: { say: ["You sing the lullaby with your hand on the Stump. The beat slows a little. The flowers, open at noon, close slowly.",
                    "They closed. Like before. The way they should close.",
                    "When you stop singing, the flowers take a while to open again. But they open."] },
    } },

    "e4-estatua": { who: { yunque: "Yunque, smith" }, nodes: {
      a: { say: ["At the foot of the Heart's third statue, the faceless smith with slag stuck to its base, Yunque is kneeling. His arm is grey up to the shoulder. He rests it on the stone as if they were family.",
                 "I come every week. I used to pray. Now I talk to him. It's like talking to a shift mate who's retired.",
                 "Look at the base. The statue's slag and the slag on my hands are the same. Whoever made this statue knew what would happen. They made it as a warning. And we prayed to it."],
           opts: ["“Say his name out loud.”", "“What do you say to him when you talk?”", "“Leave the Bell. You've one arm left.”", "“Finish the Bell. It's what you want.”"] },
      nombre: { say: ["Yunque takes the folded paper out of the amulet. He unfolds it with his good hand. He reads the name out loud, once, strongly.",
                      "People passing through the Heart stop. Someone repeats it. Another. The first smith's name runs round the square, mouth to mouth, after a thousand years.",
                      "There. He has a name again. He isn't a saint anymore. He's one of us. Now I can stop praying to him and start remembering him."] },
      dice: { say: ["I tell him how the Bell is going. How many have gone to the Ford with grey hands. I ask him if it weighed on him too.",
                    "He doesn't answer. But the slag on the base is always warm. There's something in there, still. Like the forty in the Caves."] },
      dejar: { say: ["Leave? With the Bell almost done?",
                     "He looks at his arm. He moves it a little. It creaks.",
                     "One arm. Well. With one arm you can carry a grandchild. With a stone arm, you can't. I'm going to the Ford. Let someone else finish it. Or nobody."] },
      terminar: { say: ["Yes. I'll finish it. It seems that's what I came into the world to do.",
                        "He gets up with effort. You give him a hand to help him up. The other weighs like a real anvil.",
                        "When it rings, I'll be there. Even if I'm all stone. Let someone put me beside him, on the base."] },
    } },

    "e4-llegan": { who: { retama: "Retama, keeper of the Stump", cobre: "Cobre, of the Houses" }, nodes: {
      a: { say: ["The peoples start arriving at the Heart. Not all together: little by little, in groups, with what they have. Woodcutters with resin, miners with carved stones, Houses folk with papers.",
                 "They camp around the Stump, each people in its place, not mixing. There are separate fires. There are looks.",
                 "The Houses brought chairs. Nobody else brought chairs. They're already looking at us because of the chairs.",
                 "Each people built its fire far from the others. If they're going to gather to talk about the Root, let them gather round the same fire first."],
           opts: ["Build a single fire in the middle", "Hand out the Houses' chairs", "Let each people settle in its own way"] },
      fuego: { say: ["You gather wood from every people: a log from the Forest, Court charcoal, a plank from the baths, a scrap of Heights tarp. You build a big fire in the middle.",
                     "At first nobody comes near. Then a Quarter kid. Then Pizca, from the tunnels. Then the old folk, to warm their hands.",
                     "Like that. The fire belongs to nobody and everyone needs it. Same as the Root."] },
      sillas: { say: ["Hand out the chairs? They belong to my House.",
                      "He looks at you. He looks at the workers sitting on the ground, grey hands on their knees.",
                      "Fine. My mother already sold everything else. Let the chairs go too.",
                      "Cobre carries the chairs himself, one by one, to the oldest of each people. When he's done, he sits on the ground."] },
      dejar: { say: ["Each people stays at its own fire. That night there are nine fires in the Heart and nine different songs, none of them the lullaby.",
                     "Nine fires. Well. At least they came. That's more than happened last time."] },
    } },

    "e4-pruebas": { who: { fogarin: "Fogarín, Master of the Guild", escoria: "Escoria, worker" }, nodes: {
      a: { say: ["In the Heart, Fogarín and Escoria sit on the same bench, not looking at each other. The test bell hangs from the scaffold nearby. Nobody has rung it for a month.",
                 "I was telling the Master that the test bell keeps the Root quiet for an hour. And that in that hour, in the Crater, the deep furnaces cool by themselves.",
                 "And I was telling her that means it works. That if a small bell gives an hour, the great one gives forever. And the furnaces cool forever.",
                 "And I asked him: and what else cools forever? He didn't answer."],
           opts: ["“I went down to the Deep. There are hundreds of tied bells.”", "“In the Caves there are forty workers made of stone.”", "“Ring the test bell again and everyone listen.”", "“Neither of you knows. You have to ask the nine.”"] },
      atadas: { say: ["I know. I saw them. Someone made them before. Someone tied them.",
                      "And it doesn't scare you?",
                      "Everything scares me. It scares me that they tied them because they worked too well. It scares me that they tied them because they didn't work. I don't know which scares me more."] },
      cuarenta: { say: ["Forty. Like us, but before. They kept working until they were stone.",
                        "And the Bell ends that. Nobody else goes down. Nobody else turns to stone. That's why I'm making it, Escoria. For the forty.",
                        "The forty also thought they were making something so nobody else would have to go down. Surely."] },
      tocar: { say: ["Fogarín gets up. He rings the test bell once. The note travels down through the ground.",
                     "The whole Heart goes silent. Not the silence of people keeping quiet: a silence from below, as if someone had switched off something that always sounded without anyone hearing it.",
                     "An hour later, when the background noise returns, three creatures that were asleep by the Stump don't wake up.",
                     "Is that sleep?",
                     "Fogarín doesn't answer. He sits back down on the bench, closer to her."] },
      nueve: { say: ["The nine? The Smith, the Houses, the Court and the fishers deciding about my Bell?",
                     "Our Bell. I hammered it too. With these hands.",
                     "Fogarín looks at her. He looks at her hands, grey to the wrist. Then at his own.",
                     "Fine. The nine. If they come together. If they don't, I decide. Let nobody say I didn't wait."] },
    } },

    "e4-vispera": { who: { fogarin: "Fogarín, Master of the Guild" }, nodes: {
      a: { say: ["The night before they bring the great Bell down to the Heart, Fogarín is alone in the Guild workshop, with a lamp. The Bell is covered with a tarp, enormous, red underneath.",
                 "Come in. I can't sleep. I'm eighty-four and I've never been able to sleep the night before a casting. This is the last one.",
                 "I grew up among the Tides. Ola pulled me out of the water when I fell off the jetty. I owed her a life. And what I did with it was boil their lake. How do you pay for that?"],
           opts: ["“Your grandfather's grandfather is on Ébano's list.”", "“You carved your hand on the wall of the living.”", "“You don't pay. You stop charging.”", "“Don't bring it down tomorrow. One more night.”", "Sit with him until dawn"] },
      lista: { say: ["Yes. With a grey hand. My family has been forging that metal since before it had a name. And before someone erased it.",
                     "I thought the Bell was the way to end that. Maybe it's the way to end it as always: with someone else who doesn't remember."] },
      pared: { say: ["I carved it. When I die, they'll find it there. Among the workers'. Not up top, in the masters' hall.",
                     "It's the only thing I've done in my life without anyone asking me and without anyone paying me. It did me good. Strange."] },
      cobrar: { say: ["Stop charging. Ola used to say that. Charge little and take less.",
                      "He stares at the tarp. Then he takes a paper from a drawer and signs it: the furnaces under the Lake, all of them, close the next day. Not two. All.",
                      "It's not enough. It's never enough. But it's what I know how to do: sign papers. She taught me to swim. I know how to sign."] },
      noche: { say: ["One more night. What for?",
                     "You tell him: so every people can reach the Heart. So nobody brings it down without the nine seeing.",
                     "One more night. Fine. I'll give it. To them and to me. I wasn't going to sleep anyway."] },
      sentarse: { say: ["You sit on a bench beside him. You don't talk much. He tells stories from when he was an apprentice, about the bellows that coughed, about a Caretaker who helped him pull a chain many years ago.",
                        "It was you. It was always you. I don't remember your face from back then anymore. But I remember nobody else helped me pull.",
                        "Dawn comes. Fogarín gets up, puts on his apron and uncovers the Bell."] },
    } },

    "e4-cantores": { who: { romanza: "Romanza, messenger", pizarra: "Pizarra, teacher" }, nodes: {
      a: { say: ["In the Heart, on the last night before deciding, someone wonders aloud who knows the whole lullaby. Not the one from the stories: the real one, with every verse.",
                 "Few stand up. Romanza, the Heights messenger, with her drum. Pizarra, the Meadow teacher, chalk in her hair. An old man from the Deep. A girl from the Hondura. Nobody else.",
                 "Five. To sing it properly you need nine peoples. We're five people.",
                 "The kids at my school know it. But off-key. And they made up half the verses."],
           opts: ["“Let the five of you sing it. Now.”", "“Teach it to everyone tonight.”", "“Let the kids sing it, with their made-up verses.”"] },
      cantar: { say: ["The five stand together at the foot of the Stump. They sing. Romanza keeps the beat on her drum. The lullaby sounds thin, full of gaps, but whole.",
                      "The Stump stops beating fast. The red roots darken a little. The creatures asleep by the roots open their eyes.",
                      "It works. With five it works a little. With nine, what would happen?"] },
      ensenar: { say: ["All night, Romanza and Pizarra go from fire to fire teaching the lullaby. Verse by verse. Some fall asleep. Others learn it.",
                       "By dawn, two hundred people know it. Badly. But they know it.",
                       "Two hundred. It's not in the curriculum. But it's the best class I've ever taught."] },
      chicos: { say: ["Pizarra brings her pupils. The kids stand in a ring around the Stump and sing the lullaby the way they learned it: off-key, fast, with one verse about a cup and another about a dog.",
                      "The grown-ups laugh. Then they go quiet. The Stump calms anyway.",
                      "With made-up verses. I didn't know you could. Maybe the lullaby was never the words. Maybe it was someone singing it."] },
    } },
  });

})(window.EVEVENTS_EN);
